import React, { useState, useRef, useEffect, useCallback } from 'react';
import { GoogleGenAI, LiveServerMessage, Modality } from '@google/genai';
import { Header } from './components/Header';
import { ClassificationCard } from './components/ClassificationCard';
import { TrashCategory, GroundingLink } from './types';
import { encode, decode, decodeAudioData } from './utils/audio-utils';
import { MapPinOff } from 'lucide-react';

const FRAME_RATE = 2;
const JPEG_QUALITY = 0.5;

const App: React.FC = () => {
  const [isConnected, setIsConnected] = useState(false);
  const [currentCategory, setCurrentCategory] = useState<TrashCategory>(TrashCategory.UNKNOWN);
  const [itemLabel, setItemLabel] = useState("");
  const [reason, setReason] = useState("");
  const [isInitializing, setIsInitializing] = useState(false);
  const [location, setLocation] = useState<{ lat: number, lng: number } | null>(null);
  const [locationError, setLocationError] = useState(false);
  const [groundingLinks, setGroundingLinks] = useState<GroundingLink[]>([]);

  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const sessionRef = useRef<any>(null);
  const frameIntervalRef = useRef<number | null>(null);
  const audioContextRef = useRef<AudioContext | null>(null);
  const nextStartTimeRef = useRef(0);
  const sourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());

  const initAudio = useCallback(() => {
    if (!audioContextRef.current) {
      audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
    }
  }, []);

  const requestLocation = useCallback(() => {
    if ("geolocation" in navigator) {
      navigator.geolocation.getCurrentPosition(
        (position) => {
          setLocation({
            lat: position.coords.latitude,
            lng: position.coords.longitude
          });
          setLocationError(false);
        },
        (error) => {
          console.warn("Location access denied or unavailable.");
          setLocationError(true);
        }
      );
    }
  }, []);

  useEffect(() => {
    requestLocation();
  }, [requestLocation]);

  const handleAudioOutput = async (base64Audio: string) => {
    if (!audioContextRef.current) return;
    const ctx = audioContextRef.current;
    nextStartTimeRef.current = Math.max(nextStartTimeRef.current, ctx.currentTime);
    try {
      const audioBuffer = await decodeAudioData(decode(base64Audio), ctx, 24000, 1);
      const source = ctx.createBufferSource();
      source.buffer = audioBuffer;
      source.connect(ctx.destination);
      source.addEventListener('ended', () => {
        sourcesRef.current.delete(source);
      });
      source.start(nextStartTimeRef.current);
      nextStartTimeRef.current += audioBuffer.duration;
      sourcesRef.current.add(source);
    } catch (err) {
      console.error("Audio decoding error:", err);
    }
  };

  const stopAllAudio = () => {
    sourcesRef.current.forEach(source => {
      try { source.stop(); } catch (e) {}
    });
    sourcesRef.current.clear();
    nextStartTimeRef.current = 0;
  };

  const startSession = async () => {
    if (isInitializing) return;
    setIsInitializing(true);
    initAudio();

    try {
      const stream = await navigator.mediaDevices.getUserMedia({ 
        video: { facingMode: 'environment', width: { ideal: 640 }, height: { ideal: 480 } },
        audio: true 
      });

      if (videoRef.current) videoRef.current.srcObject = stream;

      const systemInstruction = `
        You are an expert Eco-Sorting Assistant with specialized knowledge in hazardous waste, electronics, and textiles.

        GOAL: Identify objects and categorize them:
        1. RECYCLE: Metals, clean glass, plastics 1, 2, 5, clean paper.
        2. ORGANIC: Food scraps, untreated wood, compostables.
        3. TRASH: Greasy boxes, multi-material packaging, sanitary waste.
        4. HAZARDOUS: Batteries, fluorescent bulbs, chemicals, paint, medical waste.
        5. ELECTRONIC: Anything with power cords, batteries, or circuit boards (e-waste).
        6. TEXTILE: Clothing, shoes, fabrics.

        USER CONTEXT:
        Current Location: ${location ? `Latitude ${location.lat}, Longitude ${location.lng}` : 'Unknown location (prompt user if needed)'}.

        SPECIAL INSTRUCTIONS:
        - When identifying HAZARDOUS, ELECTRONIC, or TEXTILE waste, prioritize safety instructions.
        - USE GOOGLE MAPS to find specific drop-off locations or recycling centers near the user's coordinates.
        - Provide names of specific local centers (e.g. "Community Recycling Center" or "Best Buy for electronics").
        - For Curbside: Briefly confirm if it's standard bin material.
        - Formatting: Start the analysis with "ITEM: [Object Name]".
      `;

      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        config: {
          systemInstruction,
          responseModalities: [Modality.AUDIO],
          speechConfig: {
            voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } }
          },
          tools: [{ googleMaps: {} }, { googleSearch: {} }],
          toolConfig: {
            retrievalConfig: {
              latLng: location ? { latitude: location.lat, longitude: location.lng } : undefined
            }
          },
          outputAudioTranscription: {}
        },
        callbacks: {
          onopen: () => {
            setIsConnected(true);
            setIsInitializing(false);
            startStreaming(stream);
          },
          onmessage: async (message: LiveServerMessage) => {
            const base64Audio = message.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
            if (base64Audio) handleAudioOutput(base64Audio);
            if (message.serverContent?.interrupted) stopAllAudio();

            // Extract grounding links if available
            const chunks = message.serverContent?.modelTurn?.groundingMetadata?.groundingChunks;
            if (chunks) {
              const links: GroundingLink[] = [];
              chunks.forEach((chunk: any) => {
                if (chunk.maps) links.push({ title: chunk.maps.title, uri: chunk.maps.uri });
                if (chunk.web) links.push({ title: chunk.web.title, uri: chunk.web.uri });
              });
              if (links.length > 0) setGroundingLinks(links);
            }

            if (message.serverContent?.outputTranscription) {
              const text = message.serverContent.outputTranscription.text;

              const itemMatch = text.match(/ITEM:\s*([^.\n]+)/i);
              if (itemMatch) setItemLabel(itemMatch[1].trim());

              const upperText = text.toUpperCase();
              if (upperText.includes('HAZARDOUS')) setCurrentCategory(TrashCategory.HAZARDOUS);
              else if (upperText.includes('ELECTRONIC') || upperText.includes('E-WASTE')) setCurrentCategory(TrashCategory.ELECTRONIC);
              else if (upperText.includes('TEXTILE') || upperText.includes('CLOTHING')) setCurrentCategory(TrashCategory.TEXTILE);
              else if (upperText.includes('RECYCLE')) setCurrentCategory(TrashCategory.RECYCLE);
              else if (upperText.includes('ORGANIC')) setCurrentCategory(TrashCategory.ORGANIC);
              else if (upperText.includes('TRASH')) setCurrentCategory(TrashCategory.TRASH);

              setReason(prev => (prev.length > 300 ? text : prev + " " + text));
            }

            if (message.serverContent?.turnComplete) {
              // Reset some temporary states for the next item if needed
            }
          },
          onerror: (e) => {
            console.error("Live session error:", e);
            setIsConnected(false);
            setIsInitializing(false);
          },
          onclose: () => {
            setIsConnected(false);
            setIsInitializing(false);
          }
        }
      });

      sessionRef.current = await sessionPromise;
    } catch (err) {
      console.error("Failed to start session:", err);
      setIsInitializing(false);
    }
  };

  const startStreaming = (stream: MediaStream) => {
    const inputAudioContext = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
    const source = inputAudioContext.createMediaStreamSource(stream);
    const scriptProcessor = inputAudioContext.createScriptProcessor(4096, 1, 1);

    scriptProcessor.onaudioprocess = (e) => {
      if (!sessionRef.current) return;
      const inputData = e.inputBuffer.getChannelData(0);
      const l = inputData.length;
      const int16 = new Int16Array(l);
      for (let i = 0; i < l; i++) {
        int16[i] = inputData[i] * 32768;
      }
      const pcmBlob = {
        data: encode(new Uint8Array(int16.buffer)),
        mimeType: 'audio/pcm;rate=16000'
      };
      sessionRef.current.sendRealtimeInput({ media: pcmBlob });
    };

    source.connect(scriptProcessor);
    scriptProcessor.connect(inputAudioContext.destination);

    const canvas = canvasRef.current;
    const video = videoRef.current;
    if (canvas && video) {
      const ctx = canvas.getContext('2d');
      frameIntervalRef.current = window.setInterval(() => {
        if (!sessionRef.current || video.paused || video.ended) return;
        canvas.width = 640;
        canvas.height = 480;
        ctx?.drawImage(video, 0, 0, 640, 480);
        canvas.toBlob((blob) => {
          if (blob) {
            const reader = new FileReader();
            reader.onloadend = () => {
              const base64Data = (reader.result as string).split(',')[1];
              sessionRef.current.sendRealtimeInput({
                media: { data: base64Data, mimeType: 'image/jpeg' }
              });
            };
            reader.readAsDataURL(blob);
          }
        }, 'image/jpeg', JPEG_QUALITY);
      }, 1000 / FRAME_RATE);
    }
  };

  const stopSession = () => {
    if (frameIntervalRef.current) clearInterval(frameIntervalRef.current);
    if (sessionRef.current) sessionRef.current.close();
    if (videoRef.current?.srcObject) {
      (videoRef.current.srcObject as MediaStream).getTracks().forEach(track => track.stop());
      videoRef.current.srcObject = null;
    }
    stopAllAudio();
    setIsConnected(false);
    setCurrentCategory(TrashCategory.UNKNOWN);
    setItemLabel("");
    setReason("");
    setGroundingLinks([]);
  };

  return (
    <div className="relative h-screen w-full bg-slate-950 flex flex-col items-center justify-center overflow-hidden">
      <Header isConnected={isConnected} />

      <div className="absolute inset-0 z-0">
        <video 
          ref={videoRef} 
          autoPlay 
          playsInline 
          muted 
          className="w-full h-full object-cover opacity-80"
        />
        <canvas ref={canvasRef} className="hidden" />
        <div className="absolute inset-0 bg-gradient-to-t from-slate-950 via-transparent to-slate-950/40 pointer-events-none" />
      </div>

      <div className="relative z-10 w-full max-w-md px-6 flex flex-col gap-6">

        <ClassificationCard 
          category={currentCategory} 
          item={itemLabel} 
          reason={reason} 
          locationAccess={!!location}
          links={groundingLinks}
        />

        {locationError && !location && (
          <div className="flex items-center gap-3 p-3 bg-amber-500/20 border border-amber-500/40 rounded-2xl animate-pulse">
            <MapPinOff className="w-5 h-5 text-amber-500 shrink-0" />
            <div className="flex-1">
              <p className="text-[10px] font-black uppercase text-amber-500">Location Disabled</p>
              <p className="text-xs text-slate-400">Enable GPS to find nearby recycling centers.</p>
            </div>
            <button 
              onClick={requestLocation}
              className="px-2 py-1 bg-amber-500 text-white text-[10px] font-bold rounded-lg"
            >
              RETRY
            </button>
          </div>
        )}

        <div className="flex flex-col gap-4">
          {!isConnected ? (
            <button
              onClick={startSession}
              disabled={isInitializing}
              className={`w-full py-5 rounded-2xl text-xl font-black transition-all shadow-2xl flex items-center justify-center gap-3 tracking-tighter
                ${isInitializing 
                  ? 'bg-slate-800 text-slate-500 cursor-not-allowed' 
                  : 'bg-emerald-500 hover:bg-emerald-400 text-white active:scale-95 border-b-4 border-emerald-700'
                }`}
            >
              {isInitializing ? (
                <>
                  <div className="w-6 h-6 border-4 border-slate-600 border-t-white rounded-full animate-spin" />
                  ANALYZING ENV...
                </>
              ) : (
                <>START ECO SCAN</>
              )}
            </button>
          ) : (
            <button
              onClick={stopSession}
              className="w-full py-5 rounded-2xl text-xl font-black bg-rose-600 hover:bg-rose-500 text-white transition-all shadow-2xl active:scale-95 border-b-4 border-rose-800 tracking-tighter"
            >
              STOP SESSION
            </button>
          )}

          <p className="text-center text-slate-500 text-[10px] font-black tracking-widest uppercase">
            AI Multi-Modal Sorter • Real-time Processing
          </p>
        </div>
      </div>

      <div className="absolute bottom-8 left-8 right-8 flex justify-between items-center pointer-events-none opacity-40">
        <div className="flex gap-4">
          <div className="w-12 h-1 border-t border-slate-600" />
        </div>
        <span className="text-[10px] font-black tracking-[0.3em] uppercase text-slate-400">
          Earth First • Zero Waste AI
        </span>
        <div className="flex gap-4">
          <div className="w-12 h-1 border-t border-slate-600" />
        </div>
      </div>
    </div>
  );
};

export default App;

