import React, { useState, useRef, useEffect, useCallback } from 'react';
import { GoogleGenAI, LiveServerMessage, Modality } from '@google/genai';
import { Header } from './components/Header';
import { ClassificationCard } from './components/ClassificationCard';
import { TrashCategory, GroundingLink } from './types';
import { encode, decode, decodeAudioData } from './utils/audio-utils';
import { sounds } from './utils/sound-effects';
import { MapPinOff, Scan, Target, CircleDot } from 'lucide-react';

const FRAME_RATE = 2;
const JPEG_QUALITY = 0.5;

const App: React.FC = () => {
  const [isConnected, setIsConnected] = useState(false);
  const [currentCategory, setCurrentCategory] = useState<TrashCategory>(TrashCategory.UNKNOWN);
  const [itemLabel, setItemLabel] = useState("");
  const [reason, setReason] = useState("");
  const [isInitializing, setIsInitializing] = useState(false);
  const [location, setLocation] = useState<{ lat: number, lng: number } | null>(null);
  const [locationError, setLocationError] = useState(false);
  const [groundingLinks, setGroundingLinks] = useState<GroundingLink[]>([]);

  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const sessionRef = useRef<any>(null);
  const frameIntervalRef = useRef<number | null>(null);
  const audioContextRef = useRef<AudioContext | null>(null);
  const nextStartTimeRef = useRef(0);
  const sourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());

  // Track last identified item to trigger success sound only once per new detection
  const lastItemRef = useRef("");

  const initAudio = useCallback(() => {
    if (!audioContextRef.current) {
      audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
    }
  }, []);

  const requestLocation = useCallback(() => {
    if ("geolocation" in navigator) {
      navigator.geolocation.getCurrentPosition(
        (position) => {
          setLocation({
            lat: position.coords.latitude,
            lng: position.coords.longitude
          });
          setLocationError(false);
        },
        (error) => {
          console.warn("Location access denied.");
          setLocationError(true);
        }
      );
    }
  }, []);

  useEffect(() => {
    requestLocation();
  }, [requestLocation]);

  const handleAudioOutput = async (base64Audio: string) => {
    if (!audioContextRef.current) return;
    const ctx = audioContextRef.current;
    nextStartTimeRef.current = Math.max(nextStartTimeRef.current, ctx.currentTime);
    try {
      const audioBuffer = await decodeAudioData(decode(base64Audio), ctx, 24000, 1);
      const source = ctx.createBufferSource();
      source.buffer = audioBuffer;
      source.connect(ctx.destination);
      source.addEventListener('ended', () => {
        sourcesRef.current.delete(source);
      });
      source.start(nextStartTimeRef.current);
      nextStartTimeRef.current += audioBuffer.duration;
      sourcesRef.current.add(source);
    } catch (err) {
      console.error("Audio decoding error:", err);
    }
  };

  const stopAllAudio = () => {
    sourcesRef.current.forEach(source => {
      try { source.stop(); } catch (e) {}
    });
    sourcesRef.current.clear();
    nextStartTimeRef.current = 0;
  };

  const startSession = async () => {
    if (isInitializing) return;
    setIsInitializing(true);
    initAudio();

    try {
      const stream = await navigator.mediaDevices.getUserMedia({ 
        video: { facingMode: 'environment', width: { ideal: 1280 }, height: { ideal: 720 } },
        audio: true 
      });

      if (videoRef.current) videoRef.current.srcObject = stream;

      const systemInstruction = `
        You are an expert Eco-Sorting Assistant. Identify items in the video stream.
        CATEGORIES: RECYCLE, ORGANIC, TRASH, HAZARDOUS, ELECTRONIC, TEXTILE.
        Location: ${location ? `${location.lat}, ${location.lng}` : 'Unknown'}.

        RULES:
        - Identify the object clearly.
        - USE GOOGLE MAPS to find nearby disposal for Hazardous/Electronic/Textile items.
        - FORMAT: Start with "ITEM: [Object Name]" then the category and reasoning.
        - Keep verbal responses concise.
      `;

      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        config: {
          systemInstruction,
          responseModalities: [Modality.AUDIO],
          speechConfig: {
            voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } }
          },
          tools: [{ googleMaps: {} }, { googleSearch: {} }],
          toolConfig: {
            retrievalConfig: {
              latLng: location ? { latitude: location.lat, longitude: location.lng } : undefined
            }
          },
          outputAudioTranscription: {}
        },
        callbacks: {
          onopen: () => {
            setIsConnected(true);
            setIsInitializing(false);
            sounds.playConnected();
            startStreaming(stream);
          },
          onmessage: async (message: LiveServerMessage) => {
            const base64Audio = message.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
            if (base64Audio) handleAudioOutput(base64Audio);
            if (message.serverContent?.interrupted) stopAllAudio();

            const chunks = message.serverContent?.modelTurn?.groundingMetadata?.groundingChunks;
            if (chunks) {
              const links: GroundingLink[] = [];
              chunks.forEach((chunk: any) => {
                if (chunk.maps) links.push({ title: chunk.maps.title, uri: chunk.maps.uri });
                if (chunk.web) links.push({ title: chunk.web.title, uri: chunk.web.uri });
              });
              if (links.length > 0) setGroundingLinks(links);
            }

            if (message.serverContent?.outputTranscription) {
              const text = message.serverContent.outputTranscription.text;
              const itemMatch = text.match(/ITEM:\s*([^.\n]+)/i);
              if (itemMatch) {
                const foundItem = itemMatch[1].trim();
                if (foundItem.toLowerCase() !== lastItemRef.current.toLowerCase()) {
                  sounds.playSuccess();
                  lastItemRef.current = foundItem;
                }
                setItemLabel(foundItem);
              }

              const upperText = text.toUpperCase();
              let detectedCategory = null;

              if (upperText.includes('HAZARDOUS')) detectedCategory = TrashCategory.HAZARDOUS;
              else if (upperText.includes('ELECTRONIC')) detectedCategory = TrashCategory.ELECTRONIC;
              else if (upperText.includes('TEXTILE')) detectedCategory = TrashCategory.TEXTILE;
              else if (upperText.includes('RECYCLE')) detectedCategory = TrashCategory.RECYCLE;
              else if (upperText.includes('ORGANIC')) detectedCategory = TrashCategory.ORGANIC;
              else if (upperText.includes('TRASH')) detectedCategory = TrashCategory.TRASH;

              if (detectedCategory && detectedCategory !== currentCategory) {
                setCurrentCategory(detectedCategory);
                // Play specific sounds
                switch(detectedCategory) {
                  case TrashCategory.RECYCLE: sounds.playRecycle(); break;
                  case TrashCategory.ORGANIC: sounds.playOrganic(); break;
                  case TrashCategory.TRASH: sounds.playTrash(); break;
                  case TrashCategory.HAZARDOUS:
                  case TrashCategory.ELECTRONIC:
                  case TrashCategory.TEXTILE: sounds.playSpecial(); break;
                }
              }

              setReason(prev => (prev.length > 200 ? text : prev + " " + text));
            }
          },
          onerror: (e) => {
            console.error("Live session error:", e);
            sounds.playError();
            setIsConnected(false);
            setIsInitializing(false);
          },
          onclose: () => {
            setIsConnected(false);
            setIsInitializing(false);
          }
        }
      });

      sessionRef.current = await sessionPromise;
    } catch (err) {
      console.error("Failed to start session:", err);
      sounds.playError();
      setIsInitializing(false);
    }
  };

  const startStreaming = (stream: MediaStream) => {
    const inputAudioContext = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
    const source = inputAudioContext.createMediaStreamSource(stream);
    const scriptProcessor = inputAudioContext.createScriptProcessor(4096, 1, 1);

    scriptProcessor.onaudioprocess = (e) => {
      if (!sessionRef.current) return;
      const inputData = e.inputBuffer.getChannelData(0);
      const l = inputData.length;
      const int16 = new Int16Array(l);
      for (let i = 0; i < l; i++) int16[i] = inputData[i] * 32768;
      const pcmBlob = {
        data: encode(new Uint8Array(int16.buffer)),
        mimeType: 'audio/pcm;rate=16000'
      };
      sessionRef.current.sendRealtimeInput({ media: pcmBlob });
    };

    source.connect(scriptProcessor);
    scriptProcessor.connect(inputAudioContext.destination);

    const canvas = canvasRef.current;
    const video = videoRef.current;
    if (canvas && video) {
      const ctx = canvas.getContext('2d');
      frameIntervalRef.current = window.setInterval(() => {
        if (!sessionRef.current || video.paused || video.ended) return;
        canvas.width = 640;
        canvas.height = 360; // 16:9 ratio
        ctx?.drawImage(video, 0, 0, 640, 360);
        canvas.toBlob((blob) => {
          if (blob) {
            const reader = new FileReader();
            reader.onloadend = () => {
              const base64Data = (reader.result as string).split(',')[1];
              sessionRef.current.sendRealtimeInput({
                media: { data: base64Data, mimeType: 'image/jpeg' }
              });
            };
            reader.readAsDataURL(blob);
          }
        }, 'image/jpeg', JPEG_QUALITY);
      }, 1000 / FRAME_RATE);
    }
  };

  const stopSession = () => {
    if (frameIntervalRef.current) clearInterval(frameIntervalRef.current);
    if (sessionRef.current) sessionRef.current.close();
    if (videoRef.current?.srcObject) {
      (videoRef.current.srcObject as MediaStream).getTracks().forEach(track => track.stop());
      videoRef.current.srcObject = null;
    }
    stopAllAudio();
    setIsConnected(false);
    setCurrentCategory(TrashCategory.UNKNOWN);
    setItemLabel("");
    setReason("");
    setGroundingLinks([]);
    lastItemRef.current = "";
  };

  return (
    <div className="relative h-screen w-full bg-slate-950 flex flex-col overflow-hidden">
      <Header isConnected={isConnected} />

      {/* Containerized Viewfinder (Slightly smaller with margin) */}
      <div className="absolute inset-0 z-0 flex items-center justify-center px-4 py-20 md:p-12 lg:p-16">
        <div className="relative w-full h-full max-w-4xl max-h-[70vh] rounded-[2.5rem] overflow-hidden border-4 border-white/5 shadow-[0_0_80px_rgba(0,0,0,0.5)]">
          <video 
            ref={videoRef} 
            autoPlay 
            playsInline 
            muted 
            className={`w-full h-full object-cover transition-all duration-1000 ease-out ${itemLabel ? 'scale-115' : 'scale-100'}`}
          />
          <canvas ref={canvasRef} className="hidden" />

          {/* Internal Viewfinder Overlay */}
          <div className="absolute inset-0 bg-gradient-to-t from-black/40 via-transparent to-black/20 pointer-events-none" />

          {/* Dynamic Scan Reticle (Responsive to Container) */}
          {isConnected && (
            <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
              <div className="relative w-48 h-48 md:w-64 md:h-64">
                <div className={`absolute inset-0 border-2 border-emerald-500/30 rounded-3xl animate-[pulse_3s_infinite] transition-transform duration-700 ${itemLabel ? 'scale-110' : 'scale-100'}`} />
                <div className="absolute top-0 left-0 w-8 h-8 border-t-4 border-l-4 border-emerald-500 rounded-tl-xl" />
                <div className="absolute top-0 right-0 w-8 h-8 border-t-4 border-r-4 border-emerald-500 rounded-tr-xl" />
                <div className="absolute bottom-0 left-0 w-8 h-8 border-b-4 border-l-4 border-emerald-500 rounded-bl-xl" />
                <div className="absolute bottom-0 right-0 w-8 h-8 border-b-4 border-r-4 border-emerald-500 rounded-br-xl" />

                <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 flex flex-col items-center">
                  <Target className={`w-8 h-8 text-emerald-500/50 animate-spin-slow transition-transform duration-700 ${itemLabel ? 'scale-125' : 'scale-100'}`} />
                  <span className="mt-4 text-[10px] font-black uppercase text-emerald-500 tracking-[0.3em] bg-black/60 px-3 py-1 rounded-full backdrop-blur-md border border-emerald-500/20 whitespace-nowrap">
                    {itemLabel ? "ID LOCKED" : "SCANNING"}
                  </span>
                </div>
              </div>
            </div>
          )}
        </div>
      </div>

      {/* Background Ambience */}
      <div className="absolute inset-0 bg-[radial-gradient(circle_at_center,_var(--tw-gradient-stops))] from-emerald-500/5 via-transparent to-transparent pointer-events-none" />

      {/* Main UI Overlay - Layout Organized Top-to-Bottom */}
      <div className="relative z-10 flex-1 flex flex-col px-6 pt-24 pb-12">

        {/* Top: Results & Instructions */}
        <div className="flex-none transition-all duration-700">
          <ClassificationCard 
            category={currentCategory} 
            item={itemLabel} 
            reason={reason} 
            locationAccess={!!location}
            links={groundingLinks}
            isAnalyzing={isConnected}
          />
        </div>

        {/* Spacer for Viewfinder */}
        <div className="flex-1 pointer-events-none" />

        {/* Bottom: Controls & Status Indicators */}
        <div className="flex-none w-full max-w-lg mx-auto flex flex-col gap-4">

          {isConnected && !itemLabel && (
             <div className="self-center px-4 py-2 bg-slate-900/60 backdrop-blur-lg border border-white/10 rounded-full flex items-center gap-3 mb-2">
               <CircleDot className="w-3 h-3 text-emerald-400 animate-pulse" />
               <span className="text-[9px] font-black text-white uppercase tracking-widest">Awaiting Identification</span>
             </div>
          )}

          {locationError && !location && (
            <div className="flex items-center gap-3 p-3 bg-amber-500/20 backdrop-blur-md border border-amber-500/40 rounded-2xl">
              <MapPinOff className="w-4 h-4 text-amber-500 shrink-0" />
              <p className="text-[10px] text-slate-200 font-bold uppercase tracking-tight">Enable GPS for local facility grounding</p>
            </div>
          )}

          <div className="flex flex-col gap-4 bg-slate-900/40 p-1 rounded-[2rem] border border-white/5 backdrop-blur-xl">
            {!isConnected ? (
              <button
                onClick={startSession}
                disabled={isInitializing}
                className={`w-full py-5 rounded-[1.8rem] text-xl font-black transition-all shadow-2xl flex items-center justify-center gap-3 tracking-tighter
                  ${isInitializing 
                    ? 'bg-slate-800 text-slate-500 cursor-not-allowed' 
                    : 'bg-emerald-600 hover:bg-emerald-500 text-white active:scale-95 border-b-4 border-emerald-800'
                  }`}
              >
                {isInitializing ? "BOOTING AI..." : "ENGAGE SCANNER"}
              </button>
            ) : (
              <button
                onClick={stopSession}
                className="w-full py-5 rounded-[1.8rem] text-lg font-black bg-rose-600/90 hover:bg-rose-600 text-white transition-all shadow-2xl active:scale-95 border-b-4 border-rose-900 tracking-tighter"
              >
                SHUTDOWN SENSOR
              </button>
            )}
          </div>

          <div className="flex justify-between items-center px-4">
             <div className="flex gap-1.5">
               {[1, 2, 3].map(i => (
                 <div key={i} className={`w-1.5 h-1.5 rounded-full transition-colors duration-500 ${isConnected ? 'bg-emerald-500 shadow-[0_0_8px_rgba(16,185,129,0.5)]' : 'bg-slate-700'}`} />
               ))}
             </div>
             <p className="text-[9px] font-black tracking-widest uppercase text-slate-500 italic">
               Sensor: {isConnected ? "OPERATIONAL" : "IDLE"} • Grounding: {location ? "ACTIVE" : "GPS REQD"}
             </p>
          </div>
        </div>
      </div>
    </div>
  );
};

