/**
 * Generates synthetic sound effects for the EcoScan UI using Web Audio API.
 */

class SoundService {
  private ctx: AudioContext | null = null;

  private getCtx() {
    if (!this.ctx) {
      this.ctx = new (window.AudioContext || (window as any).webkitAudioContext)();
    }
    return this.ctx;
  }

  private playTone(freq: number, type: OscillatorType, duration: number, volume: number = 0.1, slideTo?: number) {
    const ctx = this.getCtx();
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();

    osc.type = type;
    osc.frequency.setValueAtTime(freq, ctx.currentTime);
    if (slideTo) {
      osc.frequency.exponentialRampToValueAtTime(slideTo, ctx.currentTime + duration);
    }

    gain.gain.setValueAtTime(volume, ctx.currentTime);
    gain.gain.exponentialRampToValueAtTime(0.0001, ctx.currentTime + duration);

    osc.connect(gain);
    gain.connect(ctx.destination);

    osc.start();
    osc.stop(ctx.currentTime + duration);
  }

  playSuccess() {
    // Upward high-tech chime
    this.playTone(660, 'sine', 0.2, 0.1, 1320);
  }

  playError() {
    // Low dissonant thud
    this.playTone(150, 'sawtooth', 0.4, 0.1, 50);
  }

  playRecycle() {
    // Metallic "ting"
    this.playTone(1760, 'sine', 0.3, 0.1);
    setTimeout(() => this.playTone(2200, 'sine', 0.1, 0.05), 50);
  }

  playOrganic() {
    // Soft woody pop
    this.playTone(440, 'triangle', 0.2, 0.1, 220);
  }

  playTrash() {
    // Neutral mid-tone beep
    this.playTone(330, 'square', 0.15, 0.05);
  }

  playSpecial() {
    // Sharp alert for Hazardous/Electronic/Textile
    this.playTone(880, 'square', 0.1, 0.1);
    setTimeout(() => this.playTone(880, 'square', 0.1, 0.1), 150);
  }

  playConnected() {
    // System boot sound
    this.playTone(440, 'sine', 0.1, 0.1);
    setTimeout(() => this.playTone(554.37, 'sine', 0.1, 0.1), 100);
    setTimeout(() => this.playTone(659.25, 'sine', 0.3, 0.1), 200);
  }

  // --- Spatial Feedback Sounds ---

  playMoveCloser() {
    // Two low pulses
    this.playTone(200, 'sine', 0.1, 0.08);
    setTimeout(() => this.playTone(180, 'sine', 0.15, 0.08), 150);
  }

  playMoveBack() {
    // High-pitched double beep
    this.playTone(1200, 'sine', 0.05, 0.05);
    setTimeout(() => this.playTone(1200, 'sine', 0.05, 0.05), 100);
  }

  playHoldSteady() {
    // Calm, mid-range focus "blip"
    this.playTone(440, 'sine', 0.15, 0.05, 440);
  }
}

export const sounds = new SoundService();

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { GoogleGenAI, LiveServerMessage, Modality } from '@google/genai';
import { Header } from './components/Header';
import { ClassificationCard } from './components/ClassificationCard';
import { TrashCategory, GroundingLink } from './types';
import { encode, decode, decodeAudioData } from './utils/audio-utils';
import { sounds } from './utils/sound-effects';
import { MapPinOff, Target, CircleDot, AlertCircle, RefreshCcw, Key } from 'lucide-react';

const FRAME_RATE = 5; // Faster sensing
const JPEG_QUALITY = 0.4; // Slightly lower quality for higher speed

const App: React.FC = () => {
  const [isConnected, setIsConnected] = useState(false);
  const [currentCategory, setCurrentCategory] = useState<TrashCategory>(TrashCategory.UNKNOWN);
  const [itemLabel, setItemLabel] = useState("");
  const [reason, setReason] = useState("");
  const [feedback, setFeedback] = useState<string | null>(null);
  const [isInitializing, setIsInitializing] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [location, setLocation] = useState<{ lat: number, lng: number } | null>(null);

  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const frameIntervalRef = useRef<number | null>(null);
  const audioContextRef = useRef<AudioContext | null>(null);
  const nextStartTimeRef = useRef(0);
  const sourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());
  const lastItemRef = useRef("");
  const activeSessionRef = useRef<any>(null);

  // Track last feedback to prevent audio spam
  const lastFeedbackRef = useRef<string | null>(null);

  const initAudio = useCallback(() => {
    if (!audioContextRef.current) {
      audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
    }
  }, []);

  const requestLocation = useCallback(() => {
    if ("geolocation" in navigator) {
      navigator.geolocation.getCurrentPosition(
        (p) => setLocation({ lat: p.coords.latitude, lng: p.coords.longitude }),
        () => console.warn("Location access denied.")
      );
    }
  }, []);

  useEffect(() => {
    requestLocation();
  }, [requestLocation]);

  const handleAudioOutput = async (base64Audio: string) => {
    if (!audioContextRef.current) return;
    const ctx = audioContextRef.current;
    nextStartTimeRef.current = Math.max(nextStartTimeRef.current, ctx.currentTime);
    try {
      const audioBuffer = await decodeAudioData(decode(base64Audio), ctx, 24000, 1);
      const source = ctx.createBufferSource();
      source.buffer = audioBuffer;
      source.connect(ctx.destination);
      source.addEventListener('ended', () => sourcesRef.current.delete(source));
      source.start(nextStartTimeRef.current);
      nextStartTimeRef.current += audioBuffer.duration;
      sourcesRef.current.add(source);
    } catch (err) {
      console.error("Audio decoding error:", err);
    }
  };

  const stopAllAudio = () => {
    sourcesRef.current.forEach(source => { try { source.stop(); } catch (e) {} });
    sourcesRef.current.clear();
    nextStartTimeRef.current = 0;
  };

  const startSession = async () => {
    if (isInitializing) return;
    setError(null);
    setIsInitializing(true);
    initAudio();

    try {
      const stream = await navigator.mediaDevices.getUserMedia({ 
        video: { facingMode: 'environment', width: { ideal: 1280 }, height: { ideal: 720 } },
        audio: true 
      });

      if (videoRef.current) videoRef.current.srcObject = stream;

      const systemInstruction = `You are a real-time Eco-Sorting HUD. 
      Identify objects and categorize them: RECYCLE, ORGANIC, TRASH, HAZARDOUS, ELECTRONIC, TEXTILE.

      SPATIAL GUIDANCE:
      - If the object is too far/small, start response with "FEEDBACK: Move Closer".
      - If too close/cut off, start with "FEEDBACK: Move Back".
      - If blurry, start with "FEEDBACK: Hold Steady".
      - Otherwise, ALWAYS start with "ITEM: [Name]".

      BE EXTREMELY FAST. Keep responses under 10 words.`;

      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        config: {
          systemInstruction,
          responseModalities: [Modality.AUDIO],
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } } },
          outputAudioTranscription: {}
        },
        callbacks: {
          onopen: () => {
            setIsConnected(true);
            setIsInitializing(false);
            sounds.playConnected();
            startStreaming(stream, sessionPromise);
          },
          onmessage: async (message: LiveServerMessage) => {
            const base64Audio = message.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
            if (base64Audio) handleAudioOutput(base64Audio);
            if (message.serverContent?.interrupted) stopAllAudio();

            if (message.serverContent?.outputTranscription) {
              const text = message.serverContent.outputTranscription.text;

              // Handle Distance Feedback
              const feedbackMatch = text.match(/FEEDBACK:\s*([^.\n]+)/i);
              if (feedbackMatch) {
                const currentFeedback = feedbackMatch[1].trim();
                setFeedback(currentFeedback);

                // Trigger feedback-specific audio cues
                if (currentFeedback !== lastFeedbackRef.current) {
                  const upperFeedback = currentFeedback.toUpperCase();
                  if (upperFeedback.includes("CLOSER")) sounds.playMoveCloser();
                  else if (upperFeedback.includes("BACK")) sounds.playMoveBack();
                  else if (upperFeedback.includes("STEADY")) sounds.playHoldSteady();
                  lastFeedbackRef.current = currentFeedback;
                }

                setTimeout(() => {
                  setFeedback(null);
                  lastFeedbackRef.current = null;
                }, 3000);
              } else {
                setFeedback(null);
                lastFeedbackRef.current = null;
              }

              // Handle Item Detection
              const itemMatch = text.match(/ITEM:\s*([^.\n]+)/i);
              if (itemMatch) {
                const foundItem = itemMatch[1].trim();
                if (foundItem.toLowerCase() !== lastItemRef.current.toLowerCase()) {
                  sounds.playSuccess();
                  lastItemRef.current = foundItem;
                }
                setItemLabel(foundItem);
              }

              const upperText = text.toUpperCase();
              let detectedCategory = null;
              if (upperText.includes('HAZARDOUS')) detectedCategory = TrashCategory.HAZARDOUS;
              else if (upperText.includes('ELECTRONIC')) detectedCategory = TrashCategory.ELECTRONIC;
              else if (upperText.includes('TEXTILE')) detectedCategory = TrashCategory.TEXTILE;
              else if (upperText.includes('RECYCLE')) detectedCategory = TrashCategory.RECYCLE;
              else if (upperText.includes('ORGANIC')) detectedCategory = TrashCategory.ORGANIC;
              else if (upperText.includes('TRASH')) detectedCategory = TrashCategory.TRASH;

              if (detectedCategory && detectedCategory !== currentCategory) {
                setCurrentCategory(detectedCategory);
                switch(detectedCategory) {
                  case TrashCategory.RECYCLE: sounds.playRecycle(); break;
                  case TrashCategory.ORGANIC: sounds.playOrganic(); break;
                  case TrashCategory.TRASH: sounds.playTrash(); break;
                  default: sounds.playSpecial(); break;
                }
              }
              setReason(prev => (prev.length > 150 ? text : prev + " " + text));
            }
          },
          onerror: (e) => {
            console.error("Live session error:", e);
            setError(e.message || "Network error. Please try again.");
            sounds.playError();
            stopSession();
          },
          onclose: () => stopSession()
        }
      });

      activeSessionRef.current = await sessionPromise;
    } catch (err: any) {
      console.error("Failed to start session:", err);
      setError(err.message || "Initialization failed");
      sounds.playError();
      setIsInitializing(false);
    }
  };

  const startStreaming = (stream: MediaStream, sessionPromise: Promise<any>) => {
    const inputAudioContext = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
    const source = inputAudioContext.createMediaStreamSource(stream);
    const scriptProcessor = inputAudioContext.createScriptProcessor(4096, 1, 1);

    scriptProcessor.onaudioprocess = (e) => {
      const inputData = e.inputBuffer.getChannelData(0);
      const l = inputData.length;
      const int16 = new Int16Array(l);
      for (let i = 0; i < l; i++) int16[i] = inputData[i] * 32768;
      const pcmBlob = {
        data: encode(new Uint8Array(int16.buffer)),
        mimeType: 'audio/pcm;rate=16000'
      };
      sessionPromise.then(session => session.sendRealtimeInput({ media: pcmBlob }))
        .catch(() => {});
    };

    source.connect(scriptProcessor);
    scriptProcessor.connect(inputAudioContext.destination);

    const canvas = canvasRef.current;
    const video = videoRef.current;
    if (canvas && video) {
      const ctx = canvas.getContext('2d');
      frameIntervalRef.current = window.setInterval(() => {
        if (video.paused || video.ended) return;
        canvas.width = 640;
        canvas.height = 360;
        ctx?.drawImage(video, 0, 0, 640, 360);
        canvas.toBlob((blob) => {
          if (blob) {
            const reader = new FileReader();
            reader.onloadend = () => {
              const base64Data = (reader.result as string).split(',')[1];
              sessionPromise.then(session => session.sendRealtimeInput({
                media: { data: base64Data, mimeType: 'image/jpeg' }
              })).catch(() => {});
            };
            reader.readAsDataURL(blob);
          }
        }, 'image/jpeg', JPEG_QUALITY);
      }, 1000 / FRAME_RATE);
    }
  };

  const stopSession = () => {
    if (frameIntervalRef.current) clearInterval(frameIntervalRef.current);
    if (activeSessionRef.current) {
      try { activeSessionRef.current.close(); } catch(e) {}
      activeSessionRef.current = null;
    }
    if (videoRef.current?.srcObject) {
      (videoRef.current.srcObject as MediaStream).getTracks().forEach(track => track.stop());
      videoRef.current.srcObject = null;
    }
    stopAllAudio();
    setIsConnected(false);
    setIsInitializing(false);
    setCurrentCategory(TrashCategory.UNKNOWN);
    setItemLabel("");
    setReason("");
    setFeedback(null);
    lastItemRef.current = "";
    lastFeedbackRef.current = null;
  };

  return (
    <div className="relative h-screen w-full bg-slate-950 flex flex-col overflow-hidden">
      <Header isConnected={isConnected} />

      {/* Containerized Viewfinder */}
      <div className="absolute inset-0 z-0 flex items-center justify-center px-4 py-20 md:p-12 lg:p-16">
        <div className="relative w-full h-full max-w-4xl max-h-[70vh] rounded-[2.5rem] overflow-hidden border-4 border-white/5 shadow-[0_0_80px_rgba(0,0,0,0.5)] bg-slate-900">
          <video 
            ref={videoRef} 
            autoPlay 
            playsInline 
            muted 
            className={`w-full h-full object-cover transition-all duration-700 ease-out ${itemLabel ? 'scale-110' : 'scale-100'} ${isConnected ? 'opacity-100' : 'opacity-20'}`}
          />
          <canvas ref={canvasRef} className="hidden" />

          <div className="absolute inset-0 bg-gradient-to-t from-black/40 via-transparent to-black/20 pointer-events-none" />

          {isConnected && (
            <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
              <div className="relative w-48 h-48 md:w-64 md:h-64">
                <div className={`absolute inset-0 border-2 ${feedback ? 'border-amber-500 animate-pulse' : 'border-emerald-500/30'} rounded-3xl transition-transform duration-700 ${itemLabel ? 'scale-110' : 'scale-100'}`} />
                <div className={`absolute top-0 left-0 w-8 h-8 border-t-4 border-l-4 rounded-tl-xl ${feedback ? 'border-amber-500' : 'border-emerald-500'}`} />
                <div className={`absolute top-0 right-0 w-8 h-8 border-t-4 border-r-4 rounded-tr-xl ${feedback ? 'border-amber-500' : 'border-emerald-500'}`} />
                <div className={`absolute bottom-0 left-0 w-8 h-8 border-b-4 border-l-4 rounded-bl-xl ${feedback ? 'border-amber-500' : 'border-emerald-500'}`} />
                <div className={`absolute bottom-0 right-0 w-8 h-8 border-b-4 border-r-4 rounded-br-xl ${feedback ? 'border-amber-500' : 'border-emerald-500'}`} />
                <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 flex flex-col items-center">
                  <span className={`text-[10px] font-black uppercase tracking-[0.3em] bg-black/60 px-3 py-1 rounded-full backdrop-blur-md border border-white/10 whitespace-nowrap ${feedback ? 'text-amber-400' : 'text-emerald-400'}`}>
                    {feedback || (itemLabel ? "ID LOCKED" : "SENSING")}
                  </span>
                </div>
              </div>
            </div>
          )}
        </div>
      </div>

      <div className="relative z-10 flex-1 flex flex-col px-6 pt-24 pb-12">
        <div className="flex-none transition-all duration-700">
          {error ? (
            <div className="w-full max-w-lg mx-auto p-4 rounded-2xl border border-rose-500/30 bg-rose-500/10 backdrop-blur-md shadow-2xl flex flex-col gap-3">
              <div className="flex items-center gap-3 text-rose-400">
                <AlertCircle className="w-6 h-6" />
                <div className="flex-1">
                  <h3 className="text-sm font-black uppercase tracking-widest">System Error</h3>
                  <p className="text-xs text-rose-300/80">{error}</p>
                </div>
              </div>
              <button onClick={startSession} className="flex items-center justify-center gap-2 py-2 bg-rose-500 text-white rounded-xl text-xs font-bold hover:bg-rose-400 transition-colors">
                <RefreshCcw className="w-4 h-4" /> REBOOT HUD
              </button>
            </div>
          ) : (
            <ClassificationCard 
              category={currentCategory} 
              item={itemLabel} 
              reason={reason} 
              locationAccess={!!location}
              isAnalyzing={isConnected}
              feedback={feedback}
            />
          )}
        </div>

        <div className="flex-1 pointer-events-none" />

        <div className="flex-none w-full max-w-lg mx-auto flex flex-col gap-4">
          <div className="flex flex-col gap-4 bg-slate-900/40 p-1 rounded-[2rem] border border-white/5 backdrop-blur-xl">
            {!isConnected ? (
              <button
                onClick={startSession}
                disabled={isInitializing}
                className={`w-full py-5 rounded-[1.8rem] text-xl font-black transition-all shadow-2xl flex items-center justify-center gap-3 tracking-tighter
                  ${isInitializing 
                    ? 'bg-slate-800 text-slate-500 cursor-not-allowed' 
                    : 'bg-emerald-600 hover:bg-emerald-500 text-white active:scale-95 border-b-4 border-emerald-800'
                  }`}
              >
                {isInitializing ? "CONNECTING..." : "ACTIVATE ECO-SENSE"}
              </button>
            ) : (
              <button
                onClick={stopSession}
                className="w-full py-5 rounded-[1.8rem] text-lg font-black bg-rose-600/90 hover:bg-rose-600 text-white transition-all shadow-2xl active:scale-95 border-b-4 border-rose-900 tracking-tighter"
              >
                TERMINATE SESSION
              </button>
            )}
          </div>

          <div className="flex justify-between items-center px-4">
             <div className="flex gap-1.5">
               {[1, 2, 3].map(i => (
                 <div key={i} className={`w-1.5 h-1.5 rounded-full transition-colors duration-500 ${isConnected ? 'bg-emerald-500 shadow-[0_0_8px_rgba(16,185,129,0.5)]' : 'bg-slate-700'}`} />
               ))}
             </div>
             <p className="text-[9px] font-black tracking-widest uppercase text-slate-500 italic">
               Sense Rate: {FRAME_RATE}Hz • Grounding: {location ? "ENABLED" : "NONE"}
             </p>
          </div>
        </div>
      </div>
    </div>
  );
};

