                    {feedback || (itemLabel ? "TARGET LOCKED" : "ANALYZING")}
                  </span>
                </div>
              </div>
            </div>
          )}
        </div>
      </div>

      <div className="relative z-10 flex-1 flex flex-col px-6 pt-24 pb-12">
        <div className="flex-none">
          {error ? (
