              <div className={`absolute top-0 right-0 w-12 h-12 border-t-4 border-r-4 rounded-tr-[2rem] transition-colors duration-500 ${feedback ? 'border-amber-500' : 'border-emerald-500/80'}`} />
              <div className={`absolute bottom-0 left-0 w-12 h-12 border-b-4 border-l-4 rounded-bl-[2rem] transition-colors duration-500 ${feedback ? 'border-amber-500' : 'border-emerald-500/80'}`} />
              <div className={`absolute bottom-0 right-0 w-12 h-12 border-b-4 border-r-4 rounded-br-[2rem] transition-colors duration-500 ${feedback ? 'border-amber-500' : 'border-emerald-500/80'}`} />

              <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 flex flex-col items-center">
                <span className={`text-[11px] font-black uppercase tracking-[0.4em] bg-black/80 px-4 py-2 rounded-full backdrop-blur-xl border border-white/10 whitespace-nowrap transition-all duration-500 ${feedback ? 'text-amber-400 scale-110' : 'text-emerald-400 opacity-60'}`}>
