import React, { useState, useRef, useEffect, useCallback } from 'react';
import { GoogleGenAI } from '@google/genai';
import { Header } from './components/Header';
import { ClassificationCard } from './components/ClassificationCard';
import { TrashCategory } from './types';
import { sounds } from './utils/sound-effects';
import { AlertCircle, RefreshCcw, Camera, Scan, RotateCcw } from 'lucide-react';

const App: React.FC = () => {
  const [isCameraActive, setIsCameraActive] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [currentCategory, setCurrentCategory] = useState<TrashCategory>(TrashCategory.UNKNOWN);
  const [itemLabel, setItemLabel] = useState("");
  const [reason, setReason] = useState("");
  const [error, setError] = useState<string | null>(null);
  const [capturedImage, setCapturedImage] = useState<string | null>(null);

  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const streamRef = useRef<MediaStream | null>(null);

  const startCamera = async () => {
    setError(null);
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ 
        video: { facingMode: 'environment', width: { ideal: 1920 }, height: { ideal: 1080 } },
        audio: false 
      });
      streamRef.current = stream;
      if (videoRef.current) videoRef.current.srcObject = stream;
      setIsCameraActive(true);
      sounds.playConnected();
    } catch (err: any) {
      console.error("Camera access denied:", err);
      setError("Camera access denied. Please enable permissions.");
      sounds.playError();
    }
  };

  const stopCamera = () => {
    if (streamRef.current) {
      streamRef.current.getTracks().forEach(track => track.stop());
      streamRef.current = null;
    }
    setIsCameraActive(false);
    resetScan();
  };

  const resetScan = () => {
    setCapturedImage(null);
    setItemLabel("");
    setReason("");
    setCurrentCategory(TrashCategory.UNKNOWN);
    setIsAnalyzing(false);
  };

  const captureAndAnalyze = async () => {
    if (!videoRef.current || !canvasRef.current || isAnalyzing) return;

    setIsAnalyzing(true);
    setError(null);
    sounds.playHoldSteady();

    const canvas = canvasRef.current;
    const video = videoRef.current;
    canvas.width = video.videoWidth;
    canvas.height = video.videoHeight;
    const ctx = canvas.getContext('2d');
    ctx?.drawImage(video, 0, 0);

    const base64Data = canvas.toDataURL('image/jpeg', 0.85);
    setCapturedImage(base64Data);
    const base64Clean = base64Data.split(',')[1];

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const prompt = `Identify the object in this image and categorize it for waste management. 
      Output MUST follow this exact format:
      ITEM: [Name]
      CATEGORY: [RECYCLE, ORGANIC, TRASH, HAZARDOUS, ELECTRONIC, or TEXTILE]
      REASON: [Brief explanation of why and how to dispose in 10 words or less]`;

      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: [{
          parts: [
            { text: prompt },
            { inlineData: { data: base64Clean, mimeType: 'image/jpeg' } }
          ]
        }]
      });

      const text = response.text || "";
      parseResponse(text);
    } catch (err: any) {
      console.error("Analysis failed:", err);
      setError("Analysis failed. Please try again.");
      sounds.playError();
      setIsAnalyzing(false);
    }
  };

  const parseResponse = (text: string) => {
    const itemMatch = text.match(/ITEM:\s*(.*)/i);
    const categoryMatch = text.match(/CATEGORY:\s*(.*)/i);
    const reasonMatch = text.match(/REASON:\s*(.*)/i);

    if (itemMatch) setItemLabel(itemMatch[1].trim());
    if (reasonMatch) setReason(reasonMatch[1].trim());

    if (categoryMatch) {
      const cat = categoryMatch[1].toUpperCase();
      let finalCat = TrashCategory.TRASH;
      if (cat.includes('RECYCLE')) finalCat = TrashCategory.RECYCLE;
      else if (cat.includes('ORGANIC')) finalCat = TrashCategory.ORGANIC;
      else if (cat.includes('HAZARDOUS')) finalCat = TrashCategory.HAZARDOUS;
      else if (cat.includes('ELECTRONIC')) finalCat = TrashCategory.ELECTRONIC;
      else if (cat.includes('TEXTILE')) finalCat = TrashCategory.TEXTILE;

      setCurrentCategory(finalCat);

      // Play specific category sound
      switch(finalCat) {
        case TrashCategory.RECYCLE: sounds.playRecycle(); break;
        case TrashCategory.ORGANIC: sounds.playOrganic(); break;
        case TrashCategory.TRASH: sounds.playTrash(); break;
        default: sounds.playSpecial(); break;
      }
      sounds.playSuccess();
    }
    setIsAnalyzing(false);
  };

  return (
    <div className="relative h-screen w-full bg-slate-950 flex flex-col overflow-hidden">
      <Header isConnected={isCameraActive} />

      {/* CAMERA VIEWPORT */}
      <div className="absolute inset-0 z-0 bg-black">
        {capturedImage ? (
          <img src={capturedImage} className="w-full h-full object-cover opacity-60" alt="Captured" />
        ) : (
          <video 
            ref={videoRef} 
            autoPlay 
            playsInline 
            muted 
            className={`w-full h-full object-cover transition-opacity duration-500 ${isCameraActive ? 'opacity-100' : 'opacity-20'}`}
          />
        )}
        <canvas ref={canvasRef} className="hidden" />

        {/* OVERLAYS */}
        <div className="absolute inset-0 bg-gradient-to-b from-black/80 via-transparent to-black/60 pointer-events-none" />

        {/* VIEWPORT SCANNER UI */}
        {isCameraActive && !capturedImage && (
          <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
            <div className="relative w-64 h-64 md:w-80 md:h-80 border-2 border-emerald-500/20 rounded-[2rem]">
              <div className="absolute top-0 left-0 w-12 h-12 border-t-4 border-l-4 border-emerald-500/60 rounded-tl-[1.5rem]" />
              <div className="absolute top-0 right-0 w-12 h-12 border-t-4 border-r-4 border-emerald-500/60 rounded-tr-[1.5rem]" />
              <div className="absolute bottom-0 left-0 w-12 h-12 border-b-4 border-l-4 border-emerald-500/60 rounded-bl-[1.5rem]" />
              <div className="absolute bottom-0 right-0 w-12 h-12 border-b-4 border-r-4 border-emerald-500/60 rounded-br-[1.5rem]" />

              {/* SCANNING LINE ANIMATION */}
              <div className="absolute left-4 right-4 h-0.5 bg-emerald-500/40 shadow-[0_0_15px_rgba(16,185,129,0.5)] animate-[scan_3s_ease-in-out_infinite]" />
            </div>
          </div>
        )}
      </div>

      {/* UI CONTENT LAYER */}
      <div className="relative z-10 flex-1 flex flex-col px-6 pt-24 pb-12">

        {/* TOP POSITIONED RESULTS CARD */}
        <div className={`transition-all duration-700 transform ${itemLabel || isAnalyzing || error ? 'translate-y-0 opacity-100' : '-translate-y-10 opacity-0 pointer-events-none'}`}>
          <div className="w-full max-w-lg mx-auto">
            {error ? (
              <div className="p-4 rounded-2xl border border-rose-500/30 bg-rose-500/20 backdrop-blur-xl flex items-center gap-4">
                <AlertCircle className="w-6 h-6 text-rose-400" />
                <p className="text-sm font-bold text-rose-200">{error}</p>
                <button onClick={startCamera} className="ml-auto p-2 bg-rose-500 rounded-lg text-white">
                  <RefreshCcw className="w-4 h-4" />
                </button>
              </div>
            ) : (
              <ClassificationCard 
                category={currentCategory} 
                item={itemLabel} 
                reason={reason} 
                locationAccess={true}
                isAnalyzing={isAnalyzing}
              />
            )}
          </div>
        </div>

        <div className="flex-1" />

        {/* BOTTOM CONTROLS */}
        <div className="w-full max-w-lg mx-auto space-y-6">
          {!isCameraActive ? (
            <button
              onClick={startCamera}
              className="w-full py-6 rounded-[2.5rem] bg-emerald-500 hover:bg-emerald-400 text-white text-xl font-black tracking-tighter shadow-[0_20px_50px_rgba(16,185,129,0.3)] transition-all active:scale-95"
            >
              LAUNCH ECO-SCANNER
            </button>
          ) : (
            <div className="flex flex-col items-center gap-6">
              <div className="flex items-center gap-8">
                {capturedImage ? (
                  <button
                    onClick={resetScan}
                    className="w-16 h-16 rounded-full bg-slate-800/80 border border-white/10 backdrop-blur-xl flex items-center justify-center text-white hover:bg-slate-700 transition-all active:scale-90"
                    title="Retake"
                  >
                    <RotateCcw className="w-6 h-6" />
                  </button>
                ) : (
                  <div className="w-16 h-16" /> // Placeholder
                )}

                <button
                  onClick={captureAndAnalyze}
                  disabled={isAnalyzing}
                  className={`relative group p-2 rounded-full border-4 ${isAnalyzing ? 'border-emerald-500/20' : 'border-white'} transition-all active:scale-90`}
                >
                  <div className={`w-16 h-16 md:w-20 md:h-20 rounded-full flex items-center justify-center transition-all ${isAnalyzing ? 'bg-emerald-900 animate-pulse' : 'bg-white group-hover:bg-emerald-50'}`}>
                    {isAnalyzing ? (
                      <Scan className="w-8 h-8 md:w-10 md:h-10 text-emerald-400 animate-spin" />
                    ) : (
                      <div className="w-12 h-12 md:w-14 md:h-14 rounded-full border-2 border-slate-900/10" />
                    )}
                  </div>
                </button>

                <button
                  onClick={stopCamera}
                  className="w-16 h-16 rounded-full bg-rose-600/20 border border-rose-500/30 backdrop-blur-xl flex items-center justify-center text-rose-400 hover:bg-rose-600/30 transition-all active:scale-90"
                  title="Close"
                >
                  <RefreshCcw className="w-6 h-6 rotate-45" />
                </button>
              </div>

              <div className="px-6 py-2 bg-black/40 backdrop-blur-md rounded-full border border-white/5">
                <p className="text-[10px] font-black tracking-[0.3em] uppercase text-white/40">
                  {capturedImage ? "IMAGE CAPTURED" : "ALIGN ITEM IN BRACKETS"}
                </p>
              </div>
            </div>
          )}
        </div>
      </div>

      <style>{`
        @keyframes scan {
          0%, 100% { top: 10%; }
          50% { top: 90%; }
        }
      `}</style>
    </div>
  );
};

export default App;

import React from 'react';
