        </div>
        {locationAccess && !isAnalyzing && (
          <div className="flex items-center gap-1.5 px-2 py-0.5 bg-emerald-500/20 rounded-full text-[10px] font-black text-emerald-400">
            <MapPin className="w-3 h-3" /> GPS ACTIVE
          </div>
