              <a 
                key={idx} 
                href={link.uri} 
                target="_blank" 
                rel="noopener noreferrer"
                className="flex-none flex items-center gap-2 px-4 py-2 bg-emerald-500/20 hover:bg-emerald-500/30 rounded-xl border border-emerald-500/20 transition-all text-[11px] text-white font-bold"
              >
