import React, { useState, useRef, useEffect, useCallback } from 'react';
import { GoogleGenAI } from '@google/genai';
import { Header } from './components/Header';
import { ClassificationCard } from './components/ClassificationCard';
import { TrashCategory, GroundingLink } from './types';
import { sounds } from './utils/sound-effects';
import { AlertCircle, RefreshCcw, Camera, Scan, RotateCcw, Loader2 } from 'lucide-react';

const App: React.FC = () => {
  const [isCameraActive, setIsCameraActive] = useState(false);
  const [isInitializingCamera, setIsInitializingCamera] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [isSearchingCenters, setIsSearchingCenters] = useState(false);
  const [currentCategory, setCurrentCategory] = useState<TrashCategory>(TrashCategory.UNKNOWN);
  const [itemLabel, setItemLabel] = useState("");
  const [reason, setReason] = useState("");
  const [error, setError] = useState<string | null>(null);
  const [capturedImage, setCapturedImage] = useState<string | null>(null);
  const [groundingLinks, setGroundingLinks] = useState<GroundingLink[]>([]);
  const [userLocation, setUserLocation] = useState<{ latitude: number; longitude: number } | null>(null);

  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const streamRef = useRef<MediaStream | null>(null);

  // Initialize location
  useEffect(() => {
    if (navigator.geolocation) {
      navigator.geolocation.getCurrentPosition(
        (pos) => setUserLocation({ latitude: pos.coords.latitude, longitude: pos.coords.longitude }),
        (err) => console.warn("Geolocation warning:", err.message)
      );
    }
    return () => {
      stopCamera();
    };
  }, []);

  // Ensure video resumes when returning from captured view
  useEffect(() => {
    if (!capturedImage && isCameraActive && videoRef.current) {
      videoRef.current.play().catch(e => {
        console.warn("Auto-play resume failed, track might be dead:", e);
        // If play fails significantly, the stream might be dead - try to restart
        const track = streamRef.current?.getTracks()[0];
        if (!track || track.readyState === 'ended') {
          startCamera();
        }
      });
    }
  }, [capturedImage, isCameraActive]);

  const startCamera = async () => {
    if (isInitializingCamera) return;

    setError(null);
    setIsInitializingCamera(true);
    resetScan();

    if (streamRef.current) {
      streamRef.current.getTracks().forEach(track => track.stop());
    }

    try {
      const stream = await navigator.mediaDevices.getUserMedia({ 
        video: { 
          facingMode: 'environment', 
          width: { ideal: 1920 }, 
          height: { ideal: 1080 } 
        },
        audio: false 
      });

      streamRef.current = stream;
      if (videoRef.current) {
        videoRef.current.srcObject = stream;
        videoRef.current.onloadedmetadata = () => {
          videoRef.current?.play().catch(e => console.error("Video play failed:", e));
        };
      }

      setIsCameraActive(true);
      sounds.playConnected();
    } catch (err: any) {
      console.error("Camera access denied:", err);
      let errorMsg = "Camera access denied. Please check permissions.";
      if (err.name === 'NotAllowedError') errorMsg = "Permission denied. Please allow camera access.";
      if (err.name === 'NotFoundError') errorMsg = "No camera found.";
      if (err.name === 'NotReadableError' || err.name === 'TrackStartError') errorMsg = "Camera is already in use by another app.";
      setError(errorMsg);
      sounds.playError();
    } finally {
      setIsInitializingCamera(false);
    }
  };

  const stopCamera = () => {
    if (streamRef.current) {
      streamRef.current.getTracks().forEach(track => track.stop());
      streamRef.current = null;
    }
    if (videoRef.current) {
      videoRef.current.srcObject = null;
    }
    setIsCameraActive(false);
    resetScan();
  };

  const resetScan = () => {
    setCapturedImage(null);
    setItemLabel("");
    setReason("");
    setCurrentCategory(TrashCategory.UNKNOWN);
    setIsAnalyzing(false);
    setIsSearchingCenters(false);
    setGroundingLinks([]);
    setError(null);

    // Explicitly try to restart the existing video stream if it's there
    if (videoRef.current && videoRef.current.paused && isCameraActive) {
      videoRef.current.play().catch(() => {
        // Fallback to full restart if play fails
        startCamera();
      });
    }
  };

  const captureAndAnalyze = async () => {
    if (!videoRef.current || !canvasRef.current || isAnalyzing || isInitializingCamera) return;

    const track = streamRef.current?.getTracks()[0];
    if (!track || track.readyState === 'ended') {
      setError("Camera connection lost. Please restart.");
      startCamera();
      return;
    }

    if (!process.env.API_KEY) {
      setError("System Configuration Error: Missing API Key.");
      return;
    }

    setIsAnalyzing(true);
    setError(null);
    sounds.playHoldSteady();

    const canvas = canvasRef.current;
    const video = videoRef.current;

    try {
      canvas.width = video.videoWidth || 640;
      canvas.height = video.videoHeight || 480;
      const ctx = canvas.getContext('2d');
      if (!ctx) throw new Error("Canvas context initialization failed");

      ctx.drawImage(video, 0, 0);

      const base64Data = canvas.toDataURL('image/jpeg', 0.85);
      setCapturedImage(base64Data);
      const base64Clean = base64Data.split(',')[1];

      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const prompt = `Identify the object in this image and categorize it for waste management. 
      Output MUST follow this exact format:
      ITEM: [Short Name]
      CATEGORY: [RECYCLE, ORGANIC, TRASH, HAZARDOUS, ELECTRONIC, or TEXTILE]
      REASON: [Brief explanation of why and how to dispose in 10 words or less]`;

      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: [{
          parts: [
            { text: prompt },
            { inlineData: { data: base64Clean, mimeType: 'image/jpeg' } }
          ]
        }]
      });

      const responseText = response.text;
      if (!responseText) throw new Error("No analysis data received.");

      parseResponse(responseText);
    } catch (err: any) {
      console.error("Analysis failed:", err);
      let errorMsg = "Analysis failed. Please try again.";
      if (!navigator.onLine) errorMsg = "Network connection lost.";
      if (err.message?.includes('Safety')) errorMsg = "Item could not be analyzed due to safety filters.";

      setError(errorMsg);
      sounds.playError();
      setIsAnalyzing(false);
    }
  };

  const parseResponse = (text: string) => {
    const itemMatch = text.match(/ITEM:\s*(.*)/i);
    const categoryMatch = text.match(/CATEGORY:\s*(.*)/i);
    const reasonMatch = text.match(/REASON:\s*(.*)/i);

    if (itemMatch) setItemLabel(itemMatch[1].trim());
    if (reasonMatch) setReason(reasonMatch[1].trim());

    if (categoryMatch) {
      const cat = categoryMatch[1].toUpperCase();
      let finalCat = TrashCategory.TRASH;
      if (cat.includes('RECYCLE')) finalCat = TrashCategory.RECYCLE;
      else if (cat.includes('ORGANIC')) finalCat = TrashCategory.ORGANIC;
      else if (cat.includes('HAZARDOUS')) finalCat = TrashCategory.HAZARDOUS;
      else if (cat.includes('ELECTRONIC')) finalCat = TrashCategory.ELECTRONIC;
      else if (cat.includes('TEXTILE')) finalCat = TrashCategory.TEXTILE;

      setCurrentCategory(finalCat);

      switch(finalCat) {
        case TrashCategory.RECYCLE: sounds.playRecycle(); break;
        case TrashCategory.ORGANIC: sounds.playOrganic(); break;
        case TrashCategory.TRASH: sounds.playTrash(); break;
        default: sounds.playSpecial(); break;
      }
      sounds.playSuccess();
    } else {
      setCurrentCategory(TrashCategory.UNKNOWN);
      setError("Categorization inconclusive. Please retake.");
    }
    setIsAnalyzing(false);
  };

  const findDisposalCenters = async () => {
    if (isSearchingCenters || !itemLabel) return;

    setIsSearchingCenters(true);
    setError(null);
    sounds.playConnected();

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const prompt = `Find nearby disposal or recycling centers for "${itemLabel}" (${currentCategory}).`;

      const config: any = { tools: [{ googleMaps: {} }] };
      if (userLocation) {
        config.toolConfig = {
          retrievalConfig: {
            latLng: { latitude: userLocation.latitude, longitude: userLocation.longitude }
          }
        };
      }

      const response = await ai.models.generateContent({
        model: 'gemini-2.5-flash-latest',
        contents: prompt,
        config: config
      });

      const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;
      if (chunks) {
        const links: GroundingLink[] = chunks
          .filter((chunk: any) => chunk.maps)
          .map((chunk: any) => ({
            title: chunk.maps.title,
            uri: chunk.maps.uri
          }));

        if (links.length > 0) {
          setGroundingLinks(links);
          sounds.playSuccess();
        } else {
          setError("No disposal centers found nearby.");
        }
      } else {
        setError("No location data available for this item.");
      }
    } catch (err: any) {
      console.error("Search failed:", err);
      setError("Disposal search unavailable. Please try later.");
      sounds.playError();
    } finally {
      setIsSearchingCenters(false);
    }
  };

  return (
    <div className="relative h-screen w-full bg-slate-950 flex flex-col overflow-hidden">
      <Header isConnected={isCameraActive && !isInitializingCamera} />

      {/* CAMERA VIEWPORT */}
      <div className="absolute inset-0 z-0 bg-black">
        {capturedImage ? (
          <img 
            src={capturedImage} 
            className="w-full h-full object-cover opacity-60 transition-opacity duration-300" 
            alt="Captured" 
          />
        ) : (
          <video 
            ref={videoRef} 
            autoPlay 
            playsInline 
            muted 
            className={`w-full h-full object-cover transition-opacity duration-500 ${isCameraActive && !isInitializingCamera ? 'opacity-100' : 'opacity-0'}`}
          />
        )}
        <canvas ref={canvasRef} className="hidden" />

        <div className="absolute inset-0 bg-gradient-to-b from-black/80 via-transparent to-black/80 pointer-events-none" />

        {isCameraActive && !capturedImage && !isInitializingCamera && (
          <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
            <div className="relative w-64 h-64 md:w-80 md:h-80 border-2 border-emerald-500/20 rounded-[2.5rem]">
              <div className="absolute top-0 left-0 w-12 h-12 border-t-4 border-l-4 border-emerald-500/60 rounded-tl-[1.8rem]" />
              <div className="absolute top-0 right-0 w-12 h-12 border-t-4 border-r-4 border-emerald-500/60 rounded-tr-[1.8rem]" />
              <div className="absolute bottom-0 left-0 w-12 h-12 border-b-4 border-l-4 border-emerald-500/60 rounded-bl-[1.8rem]" />
              <div className="absolute bottom-0 right-0 w-12 h-12 border-b-4 border-r-4 border-emerald-500/60 rounded-br-[1.8rem]" />
              <div className="absolute left-4 right-4 h-0.5 bg-emerald-500/30 shadow-[0_0_20px_rgba(16,185,129,0.4)] animate-[scan_4s_linear_infinite]" />
            </div>
          </div>
        )}

        {isInitializingCamera && (
          <div className="absolute inset-0 flex flex-col items-center justify-center gap-4 bg-slate-950">
            <Loader2 className="w-12 h-12 text-emerald-500 animate-spin" />
            <p className="text-emerald-400 font-black text-xs uppercase tracking-[0.3em] animate-pulse">Initializing Sensors...</p>
          </div>
        )}
      </div>

      <div className="relative z-10 flex-1 flex flex-col px-6 pt-24 pb-12">
        <div className={`transition-all duration-700 transform ${itemLabel || isAnalyzing || error ? 'translate-y-0 opacity-100' : '-translate-y-10 opacity-0 pointer-events-none'}`}>
          <div className="w-full max-w-lg mx-auto">
            {error ? (
              <div className="p-5 rounded-3xl border border-rose-500/30 bg-rose-500/20 backdrop-blur-2xl flex items-center gap-4 shadow-2xl">
                <AlertCircle className="w-6 h-6 text-rose-400 flex-shrink-0" />
                <div className="flex-1 text-left">
                   <h4 className="text-[10px] font-black text-rose-400 uppercase tracking-widest mb-1">Status Report</h4>
                   <p className="text-xs font-bold text-rose-100 leading-tight">{error}</p>
                </div>
                <button 
                  onClick={startCamera} 
                  className="p-3 bg-rose-600 rounded-2xl text-white hover:bg-rose-500 transition-colors shadow-lg active:scale-90"
                  aria-label="Retry"
                >
                  <RefreshCcw className="w-5 h-5" />
                </button>
              </div>
            ) : (
              <ClassificationCard 
                category={currentCategory} 
                item={itemLabel} 
                reason={reason} 
                locationAccess={!!userLocation}
                isAnalyzing={isAnalyzing}
                isSearchingCenters={isSearchingCenters}
                onFindCenters={findDisposalCenters}
                links={groundingLinks}
              />
            )}
          </div>
        </div>

        <div className="flex-1" />

        <div className="w-full max-w-lg mx-auto space-y-8">
          {!isCameraActive && !isInitializingCamera ? (
            <button
              onClick={startCamera}
              className="w-full py-7 rounded-[3rem] bg-emerald-500 hover:bg-emerald-400 text-white text-2xl font-black tracking-tighter shadow-[0_20px_60px_rgba(16,185,129,0.4)] transition-all active:scale-95 border-b-4 border-emerald-700"
            >
              LAUNCH ECO-SCANNER
            </button>
          ) : (
            <div className="flex flex-col items-center gap-8">
              <div className="flex items-center gap-10">
                {capturedImage ? (
                  <button
                    onClick={resetScan}
                    className="w-16 h-16 rounded-3xl bg-slate-800/80 border border-white/10 backdrop-blur-2xl flex items-center justify-center text-white hover:bg-slate-700 transition-all active:scale-90 shadow-xl"
                    title="Retake Photo"
                  >
                    <RotateCcw className="w-7 h-7" />
                  </button>
                ) : (
                  <div className="w-16 h-16 opacity-0 pointer-events-none" />
                )}

                <button
                  onClick={captureAndAnalyze}
                  disabled={isAnalyzing || isInitializingCamera}
                  className={`relative group p-2 rounded-full border-4 ${isAnalyzing ? 'border-emerald-500/20' : 'border-white/80'} transition-all active:scale-90 shadow-2xl`}
                  title="Capture & Analyze"
                >
                  <div className={`w-20 h-20 md:w-24 md:h-24 rounded-full flex items-center justify-center transition-all ${isAnalyzing ? 'bg-emerald-950 animate-pulse' : 'bg-white group-hover:bg-emerald-50'}`}>
                    {isAnalyzing ? (
                      <Scan className="w-10 h-10 text-emerald-400 animate-spin" />
                    ) : (
                      <div className="w-14 h-14 md:w-16 md:h-16 rounded-full border-2 border-slate-900/10 flex items-center justify-center">
                         <div className="w-10 h-10 rounded-full bg-slate-200" />
                      </div>
                    )}
                  </div>
                  {!isAnalyzing && !capturedImage && (
                    <div className="absolute -top-12 left-1/2 -translate-x-1/2 px-4 py-2 bg-emerald-500 text-white text-[10px] font-black rounded-full whitespace-nowrap animate-bounce shadow-lg">
                      TAP TO SCAN
                    </div>
                  )}
                </button>

                <button
                  onClick={stopCamera}
                  className="w-16 h-16 rounded-3xl bg-rose-600/20 border border-rose-500/30 backdrop-blur-2xl flex items-center justify-center text-rose-400 hover:bg-rose-600/30 transition-all active:scale-90 shadow-xl"
                  title="Shut Down Scanner"
                >
                  <Camera className="w-7 h-7" />
