              <div className="px-8 py-3 bg-slate-900/60 backdrop-blur-xl rounded-full border border-white/10 shadow-2xl">
                <p className="text-[10px] font-black tracking-[0.4em] uppercase text-white/50 text-center">
                  {isAnalyzing ? "Processing Neural Link..." : (capturedImage ? "Frame Analyzed" : "Align Target Object")}
