  reason: string;
  item: string;
  locationAccess: boolean;
  links?: GroundingLink[];
  isAnalyzing: boolean;
  isSearchingCenters?: boolean;
  onFindCenters?: () => void;
  isReadingAloud?: boolean;
  onReadAloud?: () => void;
  feedback?: string | null;
}

export const ClassificationCard: React.FC<ClassificationCardProps> = ({ 
  category, 
  reason, 
  item, 
  locationAccess,
  links = [],
  isAnalyzing,
  isSearchingCenters,
  onFindCenters,
  isReadingAloud,
  onReadAloud,
  feedback
