import React, { useState, useRef, useEffect } from 'react';
import { GoogleGenAI, Type, Modality } from '@google/genai';
import { Header } from './components/Header';
import { ClassificationCard } from './components/ClassificationCard';
import { TrashCategory, GroundingLink, ClassificationResult } from './types';
import { sounds } from './utils/sound-effects';
import { decode, decodeAudioData } from './utils/audio-utils';
import { AlertCircle, RotateCcw, Camera, Scan, Loader2 } from 'lucide-react';

/* 
 * App.tsx
 * Main application logic for EcoScan. 
 * Handles camera initialization, frame capture, Gemini content generation for 
 * classification, grounding for nearby centers, and TTS for accessibility.
 */

const App: React.FC = () => {
  const [isCameraActive, setIsCameraActive] = useState(false);
  const [isInitializingCamera, setIsInitializingCamera] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [isSearchingCenters, setIsSearchingCenters] = useState(false);
  const [isReadingAloud, setIsReadingAloud] = useState(false);
  const [currentCategory, setCurrentCategory] = useState<TrashCategory>(TrashCategory.UNKNOWN);
  const [itemLabel, setItemLabel] = useState("");
  const [reason, setReason] = useState("");
  const [error, setError] = useState<string | null>(null);
  const [capturedImage, setCapturedImage] = useState<string | null>(null);
  const [groundingLinks, setGroundingLinks] = useState<GroundingLink[]>([]);
  const [userLocation, setUserLocation] = useState<{ latitude: number; longitude: number } | null>(null);

  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const streamRef = useRef<MediaStream | null>(null);
  const audioCtxRef = useRef<AudioContext | null>(null);

  // Initialize geolocation for mapping tools
  useEffect(() => {
    if (navigator.geolocation) {
      navigator.geolocation.getCurrentPosition(
        (pos) => setUserLocation({ latitude: pos.coords.latitude, longitude: pos.coords.longitude }),
        (err) => console.error("Geolocation error:", err)
      );
    }
  }, []);

  // Fix: startCamera handles stream cleanup and permissions
  const startCamera = async () => {
    setIsInitializingCamera(true);
    setError(null);
    try {
      const stream = await navigator.mediaDevices.getUserMedia({
        video: { facingMode: 'environment' },
        audio: false
      });
      if (videoRef.current) {
        videoRef.current.srcObject = stream;
        streamRef.current = stream;
        setIsCameraActive(true);
        sounds.playConnected();
      }
    } catch (err) {
      setError("Camera access denied. Please enable camera permissions in your browser settings.");
      sounds.playError();
    } finally {
      setIsInitializingCamera(false);
    }
  };

  // Fix: captureFrame draws the current video frame to a hidden canvas
  const captureFrame = () => {
    if (videoRef.current && canvasRef.current) {
      const canvas = canvasRef.current;
      const video = videoRef.current;
      canvas.width = video.videoWidth;
      canvas.height = video.videoHeight;
      const ctx = canvas.getContext('2d');
      if (ctx) {
        ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
        const dataUrl = canvas.toDataURL('image/jpeg', 0.8);
        setCapturedImage(dataUrl);
        return dataUrl;
      }
    }
    return null;
  };

  // Fix: handleAnalyze uses gemini-3-flash-preview with responseSchema for structured classification
  const handleAnalyze = async () => {
    const imageData = captureFrame();
    if (!imageData) return;

    setIsAnalyzing(true);
    setError(null);
    setItemLabel("");
    setReason("");
    setGroundingLinks([]);

    try {
      // Create fresh instance per call to ensure up-to-date config
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const base64Data = imageData.split(',')[1];

      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: [
          {
            parts: [
              { text: "Identify this waste item. Classify it into one of these categories: RECYCLE, ORGANIC, TRASH, HAZARDOUS, ELECTRONIC, TEXTILE. Provide a confidence score and a brief explanation of why it belongs there, plus disposal instructions." },
              { inlineData: { mimeType: 'image/jpeg', data: base64Data } }
            ]
          }
        ],
        config: {
          responseMimeType: 'application/json',
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              item: { type: Type.STRING },
              category: { type: Type.STRING, enum: Object.values(TrashCategory) },
              confidence: { type: Type.NUMBER },
              reason: { type: Type.STRING },
              disposalInstructions: { type: Type.STRING }
            },
            required: ['item', 'category', 'confidence', 'reason']
          }
        }
      });

      const result = JSON.parse(response.text || '{}') as ClassificationResult;
      setItemLabel(result.item);
      setReason(result.reason);
      setCurrentCategory(result.category);

      // Auditory feedback based on AI classification result
      switch (result.category) {
        case TrashCategory.RECYCLE: sounds.playRecycle(); break;
        case TrashCategory.ORGANIC: sounds.playOrganic(); break;
        case TrashCategory.TRASH: sounds.playTrash(); break;
        default: sounds.playSpecial(); break;
      }
    } catch (err) {
      console.error("Analysis error:", err);
      setError("Classification failed. Please ensure the item is well-lit and clearly visible.");
      sounds.playError();
    } finally {
      setIsAnalyzing(false);
    }
  };

  // Fix: handleFindCenters uses gemini-2.5-flash with googleMaps tool for grounding
  const handleFindCenters = async () => {
    if (!itemLabel) return;
    setIsSearchingCenters(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const prompt = `Identify waste disposal or recycling centers near me for ${itemLabel} (${currentCategory}). Return the most relevant facility names and their Google Maps locations.`;

      const response = await ai.models.generateContent({
        model: 'gemini-2.5-flash',
        contents: prompt,
        config: {
          tools: [{ googleMaps: {} }],
          toolConfig: {
            retrievalConfig: {
              latLng: userLocation || { latitude: 0, longitude: 0 }
            }
          }
        }
      });

      const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];
      const links: GroundingLink[] = chunks
        .filter(c => c.maps)
        .map(c => ({
          title: c.maps?.title || "Disposal Center",
          uri: c.maps?.uri || ""
        }));

      setGroundingLinks(links);
      if (links.length > 0) {
        sounds.playSuccess();
      } else {
        setError("No nearby disposal centers found for this item type.");
      }
    } catch (err) {
      console.error("Grounding error:", err);
      setError("Failed to locate nearby centers. Please check your connection.");
    } finally {
      setIsSearchingCenters(false);
    }
  };

  // Fix: handleReadAloud uses gemini-2.5-flash-preview-tts for accessibility
  const handleReadAloud = async () => {
    if (!reason) return;
    setIsReadingAloud(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: "gemini-2.5-flash-preview-tts",
        contents: [{ parts: [{ text: `EcoScan identified this as ${itemLabel}. Recommendation: ${reason}` }] }],
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: {
            voiceConfig: {
              prebuiltVoiceConfig: { voiceName: 'Kore' },
            },
          },
        },
      });

      const audioData = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
      if (audioData) {
        if (!audioCtxRef.current) {
          audioCtxRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
        }
        const buffer = await decodeAudioData(decode(audioData), audioCtxRef.current);
        const source = audioCtxRef.current.createBufferSource();
        source.buffer = buffer;
        source.connect(audioCtxRef.current.destination);
        source.onended = () => setIsReadingAloud(false);
        source.start();
      } else {
        setIsReadingAloud(false);
      }
    } catch (err) {
      console.error("TTS error:", err);
      setIsReadingAloud(false);
    }
  };

  const resetScanner = () => {
    setCapturedImage(null);
    setCurrentCategory(TrashCategory.UNKNOWN);
    setItemLabel("");
    setReason("");
    setGroundingLinks([]);
    setError(null);
  };

  return (
    <div className="min-h-screen bg-slate-950 text-white font-sans selection:bg-emerald-500/30">
      <Header isConnected={isCameraActive} />

      <main className="container mx-auto px-4 pt-24 pb-12 max-w-2xl">
        <div className="relative aspect-[3/4] rounded-[40px] overflow-hidden bg-slate-900 border border-slate-800 shadow-2xl group">
          {isCameraActive && !capturedImage ? (
            <>
              <video 
                ref={videoRef} 
                autoPlay 
                playsInline 
                muted
                className="w-full h-full object-cover"
              />
              <div className="absolute inset-0 pointer-events-none">
                <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-64 h-64 border-2 border-white/20 rounded-3xl" />
                <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-64 h-64 border border-emerald-500/30 rounded-3xl animate-pulse" />
                <div className="absolute top-4 left-1/2 -translate-x-1/2 px-3 py-1 bg-black/50 backdrop-blur-md rounded-full text-[10px] font-black tracking-widest text-emerald-400 border border-emerald-500/20 uppercase">
                  Scanner Active
                </div>
              </div>
            </>
          ) : capturedImage ? (
            <img src={capturedImage} className="w-full h-full object-cover" alt="Captured waste" />
          ) : (
            <div className="w-full h-full flex flex-col items-center justify-center p-12 text-center">
              <div className="w-20 h-20 bg-emerald-500/10 rounded-3xl flex items-center justify-center mb-6 border border-emerald-500/20">
                <Camera className="w-10 h-10 text-emerald-500" />
              </div>
              <h2 className="text-2xl font-black mb-3">EcoScan Intelligence</h2>
              <p className="text-slate-400 text-sm font-medium mb-8 leading-relaxed">
                Aim your camera at any waste item to identify materials and find the correct disposal methods instantly.
              </p>
              <button 
                onClick={startCamera}
                disabled={isInitializingCamera}
                className="flex items-center gap-2 px-8 py-4 bg-emerald-500 hover:bg-emerald-400 text-slate-950 rounded-2xl font-black text-sm uppercase tracking-widest transition-all shadow-xl shadow-emerald-500/20 disabled:opacity-50"
              >
                {isInitializingCamera ? <Loader2 className="w-5 h-5 animate-spin" /> : <Scan className="w-5 h-5" />}
                {isInitializingCamera ? "Initializing..." : "Start Scanning"}
              </button>
            </div>
          )}

          {isCameraActive && !capturedImage && (
            <div className="absolute bottom-8 left-0 right-0 flex justify-center">
              <button 
                onClick={handleAnalyze}
                disabled={isAnalyzing}
                className="w-20 h-20 rounded-full border-4 border-white/30 flex items-center justify-center p-1 hover:border-emerald-500/50 transition-all bg-black/20 backdrop-blur-sm disabled:opacity-50"
              >
                <div className="w-full h-full rounded-full bg-white hover:bg-emerald-400 transition-colors shadow-2xl" />
              </button>
            </div>
          )}

          {error && (
            <div className="absolute top-4 left-4 right-4 bg-rose-500 text-white p-4 rounded-2xl flex items-center gap-3 shadow-xl border border-rose-400/30 animate-in fade-in slide-in-from-top-4">
              <AlertCircle className="w-5 h-5 shrink-0" />
              <p className="text-xs font-bold leading-tight">{error}</p>
            </div>
          )}
        </div>

        <div className="mt-8 space-y-6">
          <ClassificationCard 
            category={currentCategory}
            item={itemLabel}
            reason={reason}
            locationAccess={!!userLocation}
            links={groundingLinks}
            isAnalyzing={isAnalyzing}
            isSearchingCenters={isSearchingCenters}
            onFindCenters={handleFindCenters}
            isReadingAloud={isReadingAloud}
            onReadAloud={handleReadAloud}
          />

          {capturedImage && !isAnalyzing && (
            <button 
              onClick={resetScanner}
              className="w-full py-4 flex items-center justify-center gap-2 text-slate-400 hover:text-white transition-colors font-black text-xs uppercase tracking-[0.2em]"
            >
              <RotateCcw className="w-4 h-4" />
              Reset Lens
            </button>
          )}
        </div>
      </main>

      <canvas ref={canvasRef} className="hidden" />
    </div>
  );
};

export default App;

