        (err) => console.error("Geolocation error:", err)
      );
    }
    return () => {
      if (streamRef.current) {
        streamRef.current.getTracks().forEach(track => track.stop());
      }
    };
  }, []);

  // Attach stream to video element whenever it mounts
  useEffect(() => {
    if (isCameraActive && !capturedImage && streamRef.current && videoRef.current) {
      videoRef.current.srcObject = streamRef.current;
    }
  }, [isCameraActive, capturedImage]);

  const startCamera = async () => {
    if (isInitializingCamera) return;

    setIsInitializingCamera(true);
    setError(null);

    // Cleanup old stream if it exists
    if (streamRef.current) {
      streamRef.current.getTracks().forEach(track => track.stop());
    }

    try {
      const stream = await navigator.mediaDevices.getUserMedia({
        video: { facingMode: 'environment' },
        audio: false
      });

      streamRef.current = stream;
      setIsCameraActive(true);
      resetScanner(false); // Don't reset camera state, just reset analysis
      sounds.playConnected();
    } catch (err: any) {
      console.error("Camera error:", err);
      if (err.name === 'NotAllowedError') {
        setError("Camera permission denied. Please allow camera access in your browser settings.");
      } else if (err.name === 'NotFoundError') {
        setError("No camera hardware detected on this device.");
      } else {
        setError("Could not access camera. Ensure you are on a secure (HTTPS) connection.");
