            required: ['item', 'category', 'confidence', 'reason']
          }
        }
      });

      const result = JSON.parse(response.text || '{}') as ClassificationResult;
      setItemLabel(result.item);
      setReason(`${result.reason} ${result.disposalInstructions || ''}`);
