          tools: [{ googleMaps: {} }],
          toolConfig: {
            retrievalConfig: {
              latLng: userLocation || { latitude: 0, longitude: 0 }
            }
          }
        }
      });

      const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];
      const links: GroundingLink[] = chunks
        .filter(c => c.maps)
        .map(c => ({
          title: c.maps?.title || "Local Disposal Center",
          uri: c.maps?.uri || ""
        }));

      setGroundingLinks(links);
      if (links.length > 0) {
        sounds.playSuccess();
      } else {
        setError("No specific centers found for this material nearby.");
      }
    } catch (err) {
      console.error("Mapping error:", err);
      setError("Failed to search for disposal centers.");
    } finally {
      setIsSearchingCenters(false);
    }
  };

  const handleReadAloud = async () => {
    if (!reason || isReadingAloud) return;
    setIsReadingAloud(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: "gemini-2.5-flash-preview-tts",
        contents: [{ parts: [{ text: `Item identified as ${itemLabel}. Category: ${currentCategory}. ${reason}` }] }],
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: {
            voiceConfig: {
              prebuiltVoiceConfig: { voiceName: 'Kore' },
            },
          },
        },
      });

      const audioData = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
      if (audioData) {
        if (!audioCtxRef.current) {
          audioCtxRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
        }
        const buffer = await decodeAudioData(decode(audioData), audioCtxRef.current);
        const source = audioCtxRef.current.createBufferSource();
        source.buffer = buffer;
        source.connect(audioCtxRef.current.destination);
        source.onended = () => setIsReadingAloud(false);
        source.start();
      } else {
        setIsReadingAloud(false);
      }
    } catch (err) {
      console.error("TTS error:", err);
      setIsReadingAloud(false);
    }
  };

  const resetScanner = (full: boolean = true) => {
    setCapturedImage(null);
    if (full) {
      setCurrentCategory(TrashCategory.UNKNOWN);
      setItemLabel("");
      setReason("");
      setGroundingLinks([]);
      setError(null);
    }
  };

  return (
    <div className="min-h-screen bg-slate-950 text-white font-sans overflow-hidden">
      <Header isConnected={isCameraActive} />

      <main className="container mx-auto px-4 pt-24 pb-8 max-w-xl h-screen flex flex-col">
        <div className="relative flex-1 rounded-[40px] overflow-hidden bg-slate-900 border border-slate-800 shadow-2xl">
          {isCameraActive && !capturedImage ? (
            <>
              <video 
                ref={videoRef} 
                autoPlay 
                playsInline 
                muted
                className="w-full h-full object-cover"
              />
              <div className="absolute inset-0 pointer-events-none flex items-center justify-center">
                <div className="w-64 h-64 border-2 border-white/20 rounded-3xl" />
                <div className="absolute top-4 left-1/2 -translate-x-1/2 px-4 py-1.5 bg-emerald-500/20 backdrop-blur-md rounded-full text-[10px] font-black tracking-widest text-emerald-400 border border-emerald-500/30 uppercase">
                  Optical Sensors Active
                </div>
              </div>
            </>
          ) : capturedImage ? (
            <img src={capturedImage} className="w-full h-full object-cover opacity-80" alt="Captured waste" />
          ) : (
            <div className="w-full h-full flex flex-col items-center justify-center p-12 text-center bg-gradient-to-b from-slate-900 to-slate-950">
              <div className="w-24 h-24 bg-emerald-500/10 rounded-[2rem] flex items-center justify-center mb-8 border border-emerald-500/20 shadow-inner">
                <Camera className="w-12 h-12 text-emerald-500" />
              </div>
              <h2 className="text-3xl font-black mb-4 tracking-tight">EcoScan AI</h2>
              <p className="text-slate-400 text-sm font-medium mb-10 leading-relaxed max-w-[280px]">
                Categorize waste instantly using advanced vision intelligence.
              </p>
              <button 
                onClick={startCamera}
                disabled={isInitializingCamera}
                className="group relative flex items-center gap-3 px-10 py-5 bg-emerald-500 hover:bg-emerald-400 text-slate-950 rounded-2xl font-black text-xs uppercase tracking-widest transition-all shadow-2xl shadow-emerald-500/20 disabled:opacity-50 active:scale-95"
              >
                {isInitializingCamera ? <Loader2 className="w-5 h-5 animate-spin" /> : <Scan className="w-5 h-5" />}
                {isInitializingCamera ? "Syncing..." : "Initialize Scanner"}
              </button>
            </div>
          )}

          {isCameraActive && !capturedImage && (
            <div className="absolute bottom-10 left-0 right-0 flex justify-center">
              <button 
                onClick={handleAnalyze}
                disabled={isAnalyzing}
                className="group w-24 h-24 rounded-full border-4 border-white/20 flex items-center justify-center p-1.5 hover:border-emerald-500/40 transition-all bg-black/30 backdrop-blur-md disabled:opacity-50 active:scale-90"
              >
                <div className="w-full h-full rounded-full bg-white shadow-xl flex items-center justify-center">
                  {isAnalyzing && <Loader2 className="w-8 h-8 text-emerald-600 animate-spin" />}
                </div>
              </button>
            </div>
          )}

          {error && (
            <div className="absolute top-6 left-6 right-6 bg-rose-500 text-white p-5 rounded-3xl flex items-center gap-4 shadow-2xl border border-rose-400/30 animate-in fade-in slide-in-from-top-6 z-20">
              <AlertCircle className="w-6 h-6 shrink-0" />
              <p className="text-xs font-bold leading-tight flex-1">{error}</p>
              <button onClick={() => setError(null)} className="text-white/60 hover:text-white font-black text-[10px] uppercase">Dismiss</button>
            </div>
          )}
        </div>

        <div className="mt-6 flex-none space-y-4">
          <ClassificationCard 
            category={currentCategory}
            item={itemLabel}
            reason={reason}
            locationAccess={!!userLocation}
            links={groundingLinks}
            isAnalyzing={isAnalyzing}
            isSearchingCenters={isSearchingCenters}
            onFindCenters={handleFindCenters}
            isReadingAloud={isReadingAloud}
            onReadAloud={handleReadAloud}
          />

          {capturedImage && !isAnalyzing && (
            <button 
              onClick={() => resetScanner(true)}
              className="w-full py-2 flex items-center justify-center gap-2 text-slate-500 hover:text-white transition-colors font-black text-[10px] uppercase tracking-[0.3em]"
            >
              <RotateCcw className="w-3 h-3" />
              Discard Frame
            </button>
          )}
        </div>
      </main>

      <canvas ref={canvasRef} className="hidden" />
    </div>
  );
};

export default App;

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { GoogleGenAI, Type, Modality } from '@google/genai';
import { Header } from './components/Header';
import { ClassificationCard } from './components/ClassificationCard';
import { TrashCategory, GroundingLink, ClassificationResult } from './types';
import { sounds } from './utils/sound-effects';
import { decode, decodeAudioData } from './utils/audio-utils';
import { AlertCircle, RotateCcw, Camera, Scan, Loader2, RefreshCcw } from 'lucide-react';

const App: React.FC = () => {
  // UI States
  const [isCameraActive, setIsCameraActive] = useState(false);
  const [isInitializingCamera, setIsInitializingCamera] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [isSearchingCenters, setIsSearchingCenters] = useState(false);
  const [isReadingAloud, setIsReadingAloud] = useState(false);

  // Data States
  const [currentCategory, setCurrentCategory] = useState<TrashCategory>(TrashCategory.UNKNOWN);
  const [itemLabel, setItemLabel] = useState("");
  const [reason, setReason] = useState("");
  const [error, setError] = useState<string | null>(null);
  const [capturedImage, setCapturedImage] = useState<string | null>(null);
  const [groundingLinks, setGroundingLinks] = useState<GroundingLink[]>([]);
  const [userLocation, setUserLocation] = useState<{ latitude: number; longitude: number } | null>(null);

  // Refs for hardware/media
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const streamRef = useRef<MediaStream | null>(null);
  const audioCtxRef = useRef<AudioContext | null>(null);

  // Initialize geolocation once
  useEffect(() => {
    if (navigator.geolocation) {
      navigator.geolocation.getCurrentPosition(
        (pos) => setUserLocation({ latitude: pos.coords.latitude, longitude: pos.coords.longitude }),
        (err) => console.warn("Geolocation warning:", err.message)
      );
    }
    return () => {
      stopCamera();
    };
  }, []);

  // Ensure stream stays attached to video element if it's active
  useEffect(() => {
    if (isCameraActive && streamRef.current && videoRef.current && !videoRef.current.srcObject) {
      videoRef.current.srcObject = streamRef.current;
      videoRef.current.play().catch(e => console.error("Auto-play failed:", e));
    }
  }, [isCameraActive, capturedImage]);

  const stopCamera = () => {
    if (streamRef.current) {
      streamRef.current.getTracks().forEach(track => track.stop());
      streamRef.current = null;
    }
    if (videoRef.current) {
      videoRef.current.srcObject = null;
    }
    setIsCameraActive(false);
  };

  const startCamera = async () => {
    if (isInitializingCamera) return;

    setIsInitializingCamera(true);
    setError(null);
    stopCamera(); // Clean start

    try {
      const stream = await navigator.mediaDevices.getUserMedia({
        video: { 
          facingMode: 'environment',
          width: { ideal: 1280 },
          height: { ideal: 720 }
        },
        audio: false
      });

      streamRef.current = stream;
      if (videoRef.current) {
        videoRef.current.srcObject = stream;
        // Wait for metadata to ensure play() works
        videoRef.current.onloadedmetadata = () => {
          videoRef.current?.play().catch(e => console.error("Playback error:", e));
        };
      }

      setIsCameraActive(true);
      resetScanner(false);
      sounds.playConnected();
    } catch (err: any) {
      console.error("Camera error:", err);
      let msg = "Camera access failed.";
      if (err.name === 'NotAllowedError') msg = "Permission denied. Please enable camera access.";
      else if (err.name === 'NotFoundError') msg = "No camera found on this device.";
      else msg = "Could not access camera. Check if another app is using it.";

      setError(msg);
      sounds.playError();
    } finally {
      setIsInitializingCamera(false);
    }
  };

  const captureFrame = () => {
    if (!videoRef.current || !canvasRef.current) return null;

    const canvas = canvasRef.current;
    const video = videoRef.current;

    // Check if video is actually playing
    if (video.readyState < 2) {
      setError("Camera feed not ready. Please wait a moment.");
      return null;
    }

    canvas.width = video.videoWidth;
    canvas.height = video.videoHeight;

    const ctx = canvas.getContext('2d');
    if (!ctx) return null;

    ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
    const dataUrl = canvas.toDataURL('image/jpeg', 0.85);
    setCapturedImage(dataUrl);
    return dataUrl;
  };

  const handleAnalyze = async () => {
    if (isAnalyzing) return;

    const imageData = captureFrame();
    if (!imageData) return;

    setIsAnalyzing(true);
    setError(null);
    setItemLabel("");
    setReason("");
    setGroundingLinks([]);
    sounds.playHoldSteady();

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const base64Data = imageData.split(',')[1];

      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: [
          {
            parts: [
              { text: "Identify this waste item. Classify it into RECYCLE, ORGANIC, TRASH, HAZARDOUS, ELECTRONIC, or TEXTILE. Return a JSON object with 'item', 'category', 'confidence', 'reason', and 'disposalInstructions'." },
              { inlineData: { mimeType: 'image/jpeg', data: base64Data } }
            ]
          }
        ],
        config: {
          responseMimeType: 'application/json',
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              item: { type: Type.STRING },
              category: { type: Type.STRING, enum: Object.values(TrashCategory) },
              confidence: { type: Type.NUMBER },
              reason: { type: Type.STRING },
              disposalInstructions: { type: Type.STRING }
            },
            required: ['item', 'category', 'reason']
          }
        }
      });

      const textResponse = response.text;
      if (!textResponse) throw new Error("Empty response from AI");

      const result = JSON.parse(textResponse) as ClassificationResult;
      setItemLabel(result.item);
      setReason(`${result.reason} ${result.disposalInstructions || ''}`);
      setCurrentCategory(result.category);

      // Auditory confirmation
      switch (result.category) {
        case TrashCategory.RECYCLE: sounds.playRecycle(); break;
        case TrashCategory.ORGANIC: sounds.playOrganic(); break;
        case TrashCategory.TRASH: sounds.playTrash(); break;
        default: sounds.playSpecial(); break;
      }
      sounds.playSuccess();
    } catch (err: any) {
      console.error("Analysis error:", err);
      setError("Analysis failed. Please try again with a clearer view of the item.");
      sounds.playError();
      setCapturedImage(null); // Return to camera on fail
    } finally {
      setIsAnalyzing(false);
    }
  };

  const handleFindCenters = async () => {
    if (!itemLabel || isSearchingCenters) return;
    setIsSearchingCenters(true);
    setError(null);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const prompt = `Find specialized recycling or disposal centers for ${itemLabel} near me.`;

      const response = await ai.models.generateContent({
        model: 'gemini-2.5-flash',
        contents: prompt,
        config: {
          tools: [{ googleMaps: {} }],
          toolConfig: {
            retrievalConfig: {
              latLng: userLocation || { latitude: 0, longitude: 0 }
            }
          }
        }
      });

      const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];
      const links = chunks
        .filter(c => c.maps)
        .map(c => ({ title: c.maps?.title || "Disposal Center", uri: c.maps?.uri || "" }));

      setGroundingLinks(links);
      if (links.length === 0) setError("No nearby facilities found for this specific item.");
      else sounds.playSuccess();
    } catch (err) {
      setError("Could not search for local centers.");
    } finally {
      setIsSearchingCenters(false);
    }
  };

  const handleReadAloud = async () => {
    if (!reason || isReadingAloud) return;
    setIsReadingAloud(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: "gemini-2.5-flash-preview-tts",
        contents: [{ parts: [{ text: `Identified as ${itemLabel}. Recommendation: ${reason}` }] }],
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } } },
        },
      });

      const audioData = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
      if (audioData) {
        if (!audioCtxRef.current) {
          audioCtxRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
        }
        const buffer = await decodeAudioData(decode(audioData), audioCtxRef.current);
        const source = audioCtxRef.current.createBufferSource();
        source.buffer = buffer;
        source.connect(audioCtxRef.current.destination);
        source.onended = () => setIsReadingAloud(false);
        source.start();
      } else {
        setIsReadingAloud(false);
      }
    } catch (err) {
      setIsReadingAloud(false);
    }
  };

  const resetScanner = (full: boolean = true) => {
    setCapturedImage(null);
    if (full) {
      setCurrentCategory(TrashCategory.UNKNOWN);
      setItemLabel("");
      setReason("");
      setGroundingLinks([]);
      setError(null);
    }
  };

  return (
    <div className="min-h-screen bg-slate-950 text-white font-sans overflow-hidden flex flex-col">
      <Header isConnected={isCameraActive} />

      <main className="flex-1 container mx-auto px-4 pt-24 pb-6 max-w-xl flex flex-col gap-6">
        <div className="relative flex-1 min-h-[300px] rounded-[3rem] overflow-hidden bg-slate-900 border border-slate-800 shadow-2xl ring-1 ring-white/10">

          {/* CAMERA FEED - ALWAYS IN DOM FOR RELIABILITY */}
          <video 
            ref={videoRef} 
            autoPlay 
            playsInline 
            muted
            className={`w-full h-full object-cover transition-opacity duration-500 ${isCameraActive && !capturedImage ? 'opacity-100' : 'opacity-0 absolute inset-0'}`}
          />

          {/* OVERLAYS */}
          {isCameraActive && !capturedImage && (
            <div className="absolute inset-0 pointer-events-none flex flex-col items-center justify-center">
              <div className="w-64 h-64 border-2 border-emerald-500/20 rounded-3xl animate-pulse" />
              <div className="mt-4 px-4 py-1.5 bg-black/40 backdrop-blur-md rounded-full text-[10px] font-black tracking-widest text-emerald-400 border border-emerald-500/20 uppercase">
                Awaiting Target...
              </div>
            </div>
          )}

          {capturedImage && (
            <img src={capturedImage} className="absolute inset-0 w-full h-full object-cover" alt="Captured" />
          )}

          {/* EMPTY STATE / INITIALIZER */}
          {!isCameraActive && !isInitializingCamera && (
            <div className="absolute inset-0 flex flex-col items-center justify-center p-10 text-center bg-slate-900">
              <div className="w-20 h-20 bg-emerald-500/10 rounded-[2rem] flex items-center justify-center mb-6 border border-emerald-500/20">
                <Camera className="w-10 h-10 text-emerald-500" />
              </div>
              <h2 className="text-2xl font-black mb-3">Vision Engine Offline</h2>
              <p className="text-slate-400 text-sm mb-8 leading-relaxed">Ready to categorize your waste items with AI-driven visual recognition.</p>
              <button 
                onClick={startCamera}
                className="flex items-center gap-3 px-8 py-4 bg-emerald-500 hover:bg-emerald-400 text-slate-950 rounded-2xl font-black text-xs uppercase tracking-widest transition-all active:scale-95 shadow-xl shadow-emerald-500/20"
              >
                <Scan className="w-5 h-5" />
                Wake Sensors
              </button>
            </div>
          )}

          {isInitializingCamera && (
            <div className="absolute inset-0 flex flex-col items-center justify-center gap-4 bg-slate-900">
              <Loader2 className="w-10 h-10 text-emerald-500 animate-spin" />
              <p className="text-[10px] font-black tracking-[0.3em] uppercase text-emerald-500/60">Calibrating Optics...</p>
            </div>
          )}

          {/* SCAN BUTTON */}
          {isCameraActive && !capturedImage && (
            <div className="absolute bottom-8 left-0 right-0 flex justify-center">
              <button 
                onClick={handleAnalyze}
                disabled={isAnalyzing}
                className="group relative w-20 h-20 rounded-full border-4 border-white/20 flex items-center justify-center p-1.5 hover:border-emerald-500/40 transition-all bg-black/40 backdrop-blur-md disabled:opacity-50 active:scale-90"
              >
                <div className="w-full h-full rounded-full bg-white shadow-2xl flex items-center justify-center">
                  {isAnalyzing && <Loader2 className="w-8 h-8 text-emerald-600 animate-spin" />}
                </div>
              </button>
            </div>
          )}

          {/* ERROR TOAST */}
          {error && (
            <div className="absolute top-6 left-6 right-6 bg-rose-600/90 backdrop-blur-xl text-white p-5 rounded-2xl flex items-center gap-4 shadow-2xl border border-rose-400/30 animate-in fade-in slide-in-from-top-4 z-50">
              <AlertCircle className="w-6 h-6 shrink-0" />
              <p className="text-[11px] font-bold leading-tight flex-1 uppercase tracking-wider">{error}</p>
              <button 
                onClick={() => isCameraActive ? resetScanner(true) : startCamera()} 
                className="bg-white/20 p-2 rounded-lg hover:bg-white/30"
              >
                <RefreshCcw className="w-4 h-4" />
              </button>
            </div>
          )}
        </div>

        {/* CLASSIFICATION RESULTS */}
        <div className="flex-none space-y-4">
          <ClassificationCard 
            category={currentCategory}
            item={itemLabel}
            reason={reason}
            locationAccess={!!userLocation}
            links={groundingLinks}
            isAnalyzing={isAnalyzing}
            isSearchingCenters={isSearchingCenters}
            onFindCenters={handleFindCenters}
            isReadingAloud={isReadingAloud}
            onReadAloud={handleReadAloud}
          />

          {capturedImage && !isAnalyzing && (
            <button 
              onClick={() => resetScanner(true)}
              className="w-full py-4 flex items-center justify-center gap-2 text-slate-500 hover:text-white transition-all font-black text-[10px] uppercase tracking-[0.4em]"
            >
              <RotateCcw className="w-3 h-3" />
              Reset Frame
            </button>
          )}
        </div>
      </main>

      <canvas ref={canvasRef} className="hidden" />
    </div>
  );
};

export default App;

import React from 'react';
import { TrashCategory, GroundingLink } from '../types';
import { Info, AlertTriangle, MapPin, ExternalLink, Zap, Shirt, Trash2, Loader2, Search, Volume2, Target } from 'lucide-react';

interface ClassificationCardProps {
  category: TrashCategory;
  reason: string;
  item: string;
  confidence?: number;
  locationAccess: boolean;
  links?: GroundingLink[];
  isAnalyzing: boolean;
  isSearchingCenters?: boolean;
  onFindCenters?: () => void;
  isReadingAloud?: boolean;
  onReadAloud?: () => void;
  feedback?: string | null;
}

export const ClassificationCard: React.FC<ClassificationCardProps> = ({ 
  category, 
  reason, 
  item, 
  confidence = 0,
  locationAccess,
  links = [],
  isAnalyzing,
  isSearchingCenters,
  onFindCenters,
  isReadingAloud,
  onReadAloud,
  feedback
}) => {
  const getStyles = () => {
    switch (category) {
      case TrashCategory.RECYCLE:
        return {
          bg: 'bg-blue-600/30',
          border: 'border-blue-400/50',
          text: 'text-blue-100',
          accent: 'bg-blue-500',
          label: 'RECYCLABLE',
          icon: <Trash2 className="w-4 h-4" />
        };
      case TrashCategory.ORGANIC:
        return {
          bg: 'bg-emerald-600/30',
          border: 'border-emerald-400/50',
          text: 'text-emerald-100',
          accent: 'bg-emerald-500',
          label: 'ORGANIC',
          icon: <Info className="w-4 h-4" />
        };
      case TrashCategory.HAZARDOUS:
        return {
          bg: 'bg-amber-600/30',
          border: 'border-amber-400/50',
          text: 'text-amber-100',
          accent: 'bg-amber-500',
          label: 'HAZARDOUS',
          icon: <AlertTriangle className="w-4 h-4" />
        };
      case TrashCategory.ELECTRONIC:
        return {
          bg: 'bg-cyan-600/30',
          border: 'border-cyan-400/50',
          text: 'text-cyan-100',
          accent: 'bg-cyan-500',
          label: 'E-WASTE',
          icon: <Zap className="w-4 h-4" />
        };
      case TrashCategory.TEXTILE:
        return {
          bg: 'bg-purple-600/30',
          border: 'border-purple-400/50',
          text: 'text-purple-100',
          accent: 'bg-purple-500',
          label: 'TEXTILES',
          icon: <Shirt className="w-4 h-4" />
        };
      case TrashCategory.TRASH:
        return {
          bg: 'bg-rose-600/30',
          border: 'border-rose-400/50',
          text: 'text-rose-100',
          accent: 'bg-rose-500',
          label: 'GENERAL WASTE',
          icon: <Trash2 className="w-4 h-4" />
        };
      default:
        return {
          bg: 'bg-slate-900/60',
          border: 'border-white/20',
          text: 'text-slate-200',
          accent: 'bg-emerald-500',
          label: 'ANALYZING',
          icon: <Loader2 className="w-4 h-4 animate-spin" />
        };
    }
  };

  const styles = getStyles();
  const showSearchButton = !isAnalyzing && (category === TrashCategory.HAZARDOUS || category === TrashCategory.ELECTRONIC || category === TrashCategory.TEXTILE);
  const confidencePercent = Math.round(confidence * 100);

  return (
    <div className={`w-full p-5 rounded-3xl border shadow-2xl backdrop-blur-2xl transition-all duration-500 
      ${styles.bg} ${styles.border}`}>

      <div className="flex items-center justify-between mb-3">
        <div className="flex items-center gap-2">
          <span className={`p-1.5 rounded-lg ${styles.accent} text-white shadow-lg`}>
            {styles.icon}
          </span>
          <span className={`text-[11px] font-black tracking-[0.2em] ${styles.text}`}>
            {isAnalyzing ? 'SYSTEM SCANNING' : styles.label}
          </span>
        </div>
        <div className="flex items-center gap-2">
          {item && !isAnalyzing && (
            <button 
              onClick={onReadAloud}
              disabled={isReadingAloud}
              className={`p-1.5 rounded-lg transition-all ${isReadingAloud ? 'bg-white/20 animate-pulse' : 'bg-white/10 hover:bg-white/20'} text-white border border-white/10`}
              title="Read inference"
            >
              {isReadingAloud ? <Loader2 className="w-4 h-4 animate-spin" /> : <Volume2 className="w-4 h-4" />}
            </button>
          )}
          {locationAccess && !isAnalyzing && (
            <div className="flex items-center gap-1.5 px-2 py-0.5 bg-emerald-500/20 rounded-full text-[10px] font-black text-emerald-400">
              <MapPin className="w-3 h-3" /> GPS ACTIVE
            </div>
          )}
        </div>
      </div>

      <div className="space-y-1.5">
        <div className="flex items-center justify-between">
          <h3 className="text-xl font-black uppercase tracking-tight text-white flex items-center gap-2">
            {isAnalyzing ? "Processing Frame..." : (item || "Ready to Scan")}
          </h3>
          {item && !isAnalyzing && confidence > 0 && (
            <div className="flex flex-col items-end gap-1">
               <div className="flex items-center gap-1 text-[10px] font-black text-white/60">
                <Target className="w-3 h-3" /> {confidencePercent}% CONFIDENCE
              </div>
            </div>
          )}
        </div>

        {item && !isAnalyzing && confidence > 0 && (
          <div className="w-full h-1 bg-black/20 rounded-full overflow-hidden mt-1 mb-2">
            <div 
              className={`h-full ${styles.accent} transition-all duration-1000 ease-out`}
              style={{ width: `${confidencePercent}%` }}
            />
          </div>
        )}

        <p className={`text-[13px] leading-relaxed font-medium ${styles.text} opacity-90`}>
          {isAnalyzing ? "Our neural network is identifying material types and disposal protocols..." : (reason || "Position the waste item and tap the shutter to begin classification.")}
        </p>
      </div>

      {showSearchButton && (
        <button 
          onClick={onFindCenters}
          disabled={isSearchingCenters}
          className="mt-4 w-full flex items-center justify-center gap-2 py-3 bg-white/10 hover:bg-white/20 disabled:opacity-50 disabled:cursor-not-allowed rounded-xl border border-white/20 transition-all text-xs font-black uppercase tracking-widest text-white shadow-xl"
        >
          {isSearchingCenters ? (
            <>
              <Loader2 className="w-4 h-4 animate-spin" />
              LOCATING CENTERS...
            </>
          ) : (
            <>
              <Search className="w-4 h-4" />
              FIND DISPOSAL CENTER NEARBY
            </>
          )}
        </button>
      )}

      {links.length > 0 && !isAnalyzing && (
        <div className="mt-4 pt-4 border-t border-white/10 flex flex-col gap-2">
          <p className="text-[10px] font-black uppercase tracking-widest text-white/50 mb-1">Nearby Locations:</p>
          <div className="flex gap-2 overflow-x-auto no-scrollbar pb-1">
            {links.map((link, idx) => (
              <a 
                key={idx} 
                href={link.uri} 
                target="_blank" 
                rel="noopener noreferrer"
                className="flex-none flex items-center gap-2 px-4 py-2 bg-emerald-500/20 hover:bg-emerald-500/30 rounded-xl border border-emerald-500/20 transition-all text-[11px] text-white font-bold"
              >
                {link.title}
                <ExternalLink className="w-3 h-3 opacity-50" />
              </a>
            ))}
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { GoogleGenAI, Type, Modality } from '@google/genai';
import { Header } from './components/Header';
import { ClassificationCard } from './components/ClassificationCard';
import { TrashCategory, GroundingLink, ClassificationResult } from './types';
import { sounds } from './utils/sound-effects';
import { decode, decodeAudioData } from './utils/audio-utils';
import { AlertCircle, RotateCcw, Camera, Scan, Loader2, RefreshCcw } from 'lucide-react';

const App: React.FC = () => {
  // UI States
  const [isCameraActive, setIsCameraActive] = useState(false);
  const [isInitializingCamera, setIsInitializingCamera] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [isSearchingCenters, setIsSearchingCenters] = useState(false);
  const [isReadingAloud, setIsReadingAloud] = useState(false);

  // Data States
  const [currentCategory, setCurrentCategory] = useState<TrashCategory>(TrashCategory.UNKNOWN);
  const [itemLabel, setItemLabel] = useState("");
  const [reason, setReason] = useState("");
  const [confidence, setConfidence] = useState(0);
  const [error, setError] = useState<string | null>(null);
  const [capturedImage, setCapturedImage] = useState<string | null>(null);
  const [groundingLinks, setGroundingLinks] = useState<GroundingLink[]>([]);
  const [userLocation, setUserLocation] = useState<{ latitude: number; longitude: number } | null>(null);

  // Refs for hardware/media
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const streamRef = useRef<MediaStream | null>(null);
  const audioCtxRef = useRef<AudioContext | null>(null);

  // Initialize geolocation once
  useEffect(() => {
    if (navigator.geolocation) {
      navigator.geolocation.getCurrentPosition(
        (pos) => setUserLocation({ latitude: pos.coords.latitude, longitude: pos.coords.longitude }),
        (err) => console.warn("Geolocation warning:", err.message)
      );
    }
    return () => {
      stopCamera();
    };
  }, []);

  // Ensure stream stays attached to video element if it's active
  useEffect(() => {
    if (isCameraActive && streamRef.current && videoRef.current && !videoRef.current.srcObject) {
      videoRef.current.srcObject = streamRef.current;
      videoRef.current.play().catch(e => console.error("Auto-play failed:", e));
    }
  }, [isCameraActive, capturedImage]);

  const stopCamera = () => {
    if (streamRef.current) {
      streamRef.current.getTracks().forEach(track => track.stop());
      streamRef.current = null;
    }
    if (videoRef.current) {
      videoRef.current.srcObject = null;
    }
    setIsCameraActive(false);
  };

  const startCamera = async () => {
    if (isInitializingCamera) return;

    setIsInitializingCamera(true);
    setError(null);
    stopCamera(); // Clean start

    try {
      const stream = await navigator.mediaDevices.getUserMedia({
        video: { 
          facingMode: 'environment',
          width: { ideal: 1280 },
          height: { ideal: 720 }
        },
        audio: false
      });

      streamRef.current = stream;
      if (videoRef.current) {
        videoRef.current.srcObject = stream;
        // Wait for metadata to ensure play() works
        videoRef.current.onloadedmetadata = () => {
          videoRef.current?.play().catch(e => console.error("Playback error:", e));
        };
      }

      setIsCameraActive(true);
      resetScanner(false);
      sounds.playConnected();
    } catch (err: any) {
      console.error("Camera error:", err);
      let msg = "Camera access failed.";
      if (err.name === 'NotAllowedError') msg = "Permission denied. Please enable camera access.";
      else if (err.name === 'NotFoundError') msg = "No camera found on this device.";
      else msg = "Could not access camera. Check if another app is using it.";

      setError(msg);
      sounds.playError();
    } finally {
      setIsInitializingCamera(false);
    }
  };

  const captureFrame = () => {
    if (!videoRef.current || !canvasRef.current) return null;

    const canvas = canvasRef.current;
    const video = videoRef.current;

    // Check if video is actually playing
    if (video.readyState < 2) {
      setError("Camera feed not ready. Please wait a moment.");
      return null;
    }

    canvas.width = video.videoWidth;
    canvas.height = video.videoHeight;

    const ctx = canvas.getContext('2d');
    if (!ctx) return null;

    ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
    const dataUrl = canvas.toDataURL('image/jpeg', 0.85);
    setCapturedImage(dataUrl);
    return dataUrl;
  };

  const handleAnalyze = async () => {
    if (isAnalyzing) return;

    const imageData = captureFrame();
    if (!imageData) return;

    setIsAnalyzing(true);
    setError(null);
    setItemLabel("");
    setReason("");
    setConfidence(0);
    setGroundingLinks([]);
    sounds.playHoldSteady();

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const base64Data = imageData.split(',')[1];

      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: [
          {
            parts: [
              { text: "Identify this waste item. Classify it into RECYCLE, ORGANIC, TRASH, HAZARDOUS, ELECTRONIC, or TEXTILE. Return a JSON object with 'item', 'category', 'confidence', 'reason', and 'disposalInstructions'. Confidence should be a number between 0 and 1." },
              { inlineData: { mimeType: 'image/jpeg', data: base64Data } }
            ]
          }
        ],
        config: {
          responseMimeType: 'application/json',
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              item: { type: Type.STRING },
              category: { type: Type.STRING, enum: Object.values(TrashCategory) },
              confidence: { type: Type.NUMBER },
              reason: { type: Type.STRING },
              disposalInstructions: { type: Type.STRING }
            },
            required: ['item', 'category', 'reason', 'confidence']
          }
        }
      });

      const textResponse = response.text;
      if (!textResponse) throw new Error("Empty response from AI");

      const result = JSON.parse(textResponse) as ClassificationResult;
      setItemLabel(result.item);
      setReason(`${result.reason} ${result.disposalInstructions || ''}`);
      setCurrentCategory(result.category);
      setConfidence(result.confidence || 0);

      // Auditory confirmation
      switch (result.category) {
        case TrashCategory.RECYCLE: sounds.playRecycle(); break;
        case TrashCategory.ORGANIC: sounds.playOrganic(); break;
        case TrashCategory.TRASH: sounds.playTrash(); break;
        default: sounds.playSpecial(); break;
      }
      sounds.playSuccess();
    } catch (err: any) {
      console.error("Analysis error:", err);
      setError("Analysis failed. Please try again with a clearer view of the item.");
      sounds.playError();
      setCapturedImage(null); // Return to camera on fail
    } finally {
      setIsAnalyzing(false);
    }
  };

  const handleFindCenters = async () => {
    if (!itemLabel || isSearchingCenters) return;
    setIsSearchingCenters(true);
    setError(null);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const prompt = `Find specialized recycling or disposal centers for ${itemLabel} near me.`;

      const response = await ai.models.generateContent({
        model: 'gemini-2.5-flash',
        contents: prompt,
        config: {
          tools: [{ googleMaps: {} }],
          toolConfig: {
            retrievalConfig: {
              latLng: userLocation || { latitude: 0, longitude: 0 }
            }
          }
        }
      });

      const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];
      const links = chunks
        .filter(c => c.maps)
        .map(c => ({ title: c.maps?.title || "Disposal Center", uri: c.maps?.uri || "" }));

      setGroundingLinks(links);
      if (links.length === 0) setError("No nearby facilities found for this specific item.");
      else sounds.playSuccess();
    } catch (err) {
      setError("Could not search for local centers.");
    } finally {
      setIsSearchingCenters(false);
    }
  };

  const handleReadAloud = async () => {
    if (!reason || isReadingAloud) return;
    setIsReadingAloud(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: "gemini-2.5-flash-preview-tts",
        contents: [{ parts: [{ text: `Identified as ${itemLabel}. Recommendation: ${reason}` }] }],
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } } },
        },
      });

      const audioData = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
      if (audioData) {
        if (!audioCtxRef.current) {
          audioCtxRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
        }
        const buffer = await decodeAudioData(decode(audioData), audioCtxRef.current);
        const source = audioCtxRef.current.createBufferSource();
        source.buffer = buffer;
        source.connect(audioCtxRef.current.destination);
        source.onended = () => setIsReadingAloud(false);
        source.start();
      } else {
        setIsReadingAloud(false);
      }
    } catch (err) {
      setIsReadingAloud(false);
    }
  };

  const resetScanner = (full: boolean = true) => {
    setCapturedImage(null);
    if (full) {
      setCurrentCategory(TrashCategory.UNKNOWN);
      setItemLabel("");
      setReason("");
      setConfidence(0);
      setGroundingLinks([]);
      setError(null);
    }
  };

  return (
    <div className="min-h-screen bg-slate-950 text-white font-sans overflow-hidden flex flex-col">
      <Header isConnected={isCameraActive} />

      <main className="flex-1 container mx-auto px-4 pt-24 pb-6 max-w-xl flex flex-col gap-6">
        <div className="relative flex-1 min-h-[300px] rounded-[3rem] overflow-hidden bg-slate-900 border border-slate-800 shadow-2xl ring-1 ring-white/10">

          {/* CAMERA FEED - ALWAYS IN DOM FOR RELIABILITY */}
          <video 
            ref={videoRef} 
            autoPlay 
            playsInline 
            muted
            className={`w-full h-full object-cover transition-opacity duration-500 ${isCameraActive && !capturedImage ? 'opacity-100' : 'opacity-0 absolute inset-0'}`}
          />

          {/* OVERLAYS */}
          {isCameraActive && !capturedImage && (
            <div className="absolute inset-0 pointer-events-none flex flex-col items-center justify-center">
              <div className="w-64 h-64 border-2 border-emerald-500/20 rounded-3xl animate-pulse" />
              <div className="mt-4 px-4 py-1.5 bg-black/40 backdrop-blur-md rounded-full text-[10px] font-black tracking-widest text-emerald-400 border border-emerald-500/20 uppercase">
                Awaiting Target...
              </div>
            </div>
          )}

          {capturedImage && (
            <img src={capturedImage} className="absolute inset-0 w-full h-full object-cover" alt="Captured" />
          )}

          {/* EMPTY STATE / INITIALIZER */}
          {!isCameraActive && !isInitializingCamera && (
            <div className="absolute inset-0 flex flex-col items-center justify-center p-10 text-center bg-slate-900">
              <div className="w-20 h-20 bg-emerald-500/10 rounded-[2rem] flex items-center justify-center mb-6 border border-emerald-500/20">
                <Camera className="w-10 h-10 text-emerald-500" />
              </div>
              <h2 className="text-2xl font-black mb-3">Vision Engine Offline</h2>
              <p className="text-slate-400 text-sm mb-8 leading-relaxed">Ready to categorize your waste items with AI-driven visual recognition.</p>
              <button 
                onClick={startCamera}
                className="flex items-center gap-3 px-8 py-4 bg-emerald-500 hover:bg-emerald-400 text-slate-950 rounded-2xl font-black text-xs uppercase tracking-widest transition-all active:scale-95 shadow-xl shadow-emerald-500/20"
              >
                <Scan className="w-5 h-5" />
                Wake Sensors
              </button>
            </div>
          )}

          {isInitializingCamera && (
            <div className="absolute inset-0 flex flex-col items-center justify-center gap-4 bg-slate-900">
              <Loader2 className="w-10 h-10 text-emerald-500 animate-spin" />
              <p className="text-[10px] font-black tracking-[0.3em] uppercase text-emerald-500/60">Calibrating Optics...</p>
            </div>
          )}

          {/* SCAN BUTTON */}
          {isCameraActive && !capturedImage && (
            <div className="absolute bottom-8 left-0 right-0 flex justify-center">
              <button 
                onClick={handleAnalyze}
                disabled={isAnalyzing}
                className="group relative w-20 h-20 rounded-full border-4 border-white/20 flex items-center justify-center p-1.5 hover:border-emerald-500/40 transition-all bg-black/40 backdrop-blur-md disabled:opacity-50 active:scale-90"
              >
                <div className="w-full h-full rounded-full bg-white shadow-2xl flex items-center justify-center">
                  {isAnalyzing && <Loader2 className="w-8 h-8 text-emerald-600 animate-spin" />}
                </div>
              </button>
            </div>
          )}

          {/* ERROR TOAST */}
          {error && (
            <div className="absolute top-6 left-6 right-6 bg-rose-600/90 backdrop-blur-xl text-white p-5 rounded-2xl flex items-center gap-4 shadow-2xl border border-rose-400/30 animate-in fade-in slide-in-from-top-4 z-50">
              <AlertCircle className="w-6 h-6 shrink-0" />
              <p className="text-[11px] font-bold leading-tight flex-1 uppercase tracking-wider">{error}</p>
              <button 
                onClick={() => isCameraActive ? resetScanner(true) : startCamera()} 
                className="bg-white/20 p-2 rounded-lg hover:bg-white/30"
              >
                <RefreshCcw className="w-4 h-4" />
              </button>
            </div>
          )}
        </div>

        {/* CLASSIFICATION RESULTS */}
        <div className="flex-none space-y-4">
          <ClassificationCard 
            category={currentCategory}
            item={itemLabel}
            confidence={confidence}
            reason={reason}
            locationAccess={!!userLocation}
            links={groundingLinks}
            isAnalyzing={isAnalyzing}
            isSearchingCenters={isSearchingCenters}
            onFindCenters={handleFindCenters}
            isReadingAloud={isReadingAloud}
            onReadAloud={handleReadAloud}
          />

          {capturedImage && !isAnalyzing && (
            <button 
              onClick={() => resetScanner(true)}
              className="w-full py-4 flex items-center justify-center gap-2 text-slate-500 hover:text-white transition-all font-black text-[10px] uppercase tracking-[0.4em]"
            >
              <RotateCcw className="w-3 h-3" />
              Reset Frame
            </button>
          )}
        </div>
      </main>

      <canvas ref={canvasRef} className="hidden" />
    </div>
  );
};

