        <div className="relative w-full lg:flex-1 aspect-[4/3] sm:aspect-video lg:aspect-auto lg:h-[calc(100vh-10rem)] max-h-[60vh] lg:max-h-none rounded-[2.5rem] overflow-hidden bg-slate-900 border border-slate-800 shadow-2xl ring-1 ring-white/10 transition-all duration-700">

          <video 
            ref={videoRef} 
            autoPlay 
            playsInline 
            muted
            className={`w-full h-full object-cover transition-opacity duration-500 ${isCameraActive && !capturedImage ? 'opacity-100' : 'opacity-0 absolute inset-0'}`}
          />

          {isCameraActive && !capturedImage && (
            <div className="absolute inset-0 pointer-events-none flex flex-col items-center">
              {/* Moved "Awaiting Target" text to the top and separated from click button area */}
              <div className="mt-12 px-5 py-2 bg-emerald-500/20 backdrop-blur-xl rounded-full text-[10px] font-black tracking-[0.3em] text-emerald-400 border border-emerald-500/30 uppercase animate-pulse shadow-lg">
                Scanning for Target...
              </div>
              <div className="flex-1 flex items-center justify-center w-full">
                <div className="w-1/2 aspect-square max-w-[200px] border-2 border-emerald-500/20 rounded-3xl animate-pulse relative">
                  <div className="absolute top-0 left-0 w-4 h-4 border-t-2 border-l-2 border-emerald-400 rounded-tl-lg" />
                  <div className="absolute top-0 right-0 w-4 h-4 border-t-2 border-r-2 border-emerald-400 rounded-tr-lg" />
                  <div className="absolute bottom-0 left-0 w-4 h-4 border-b-2 border-l-2 border-emerald-400 rounded-bl-lg" />
                  <div className="absolute bottom-0 right-0 w-4 h-4 border-b-2 border-r-2 border-emerald-400 rounded-br-lg" />
