          {!isCameraActive && !isInitializingCamera && (
            <div className="absolute inset-0 flex flex-col items-center justify-center p-8 text-center bg-slate-900/90 backdrop-blur-sm">
              <div className="w-16 h-16 sm:w-20 sm:h-20 bg-emerald-500/10 rounded-3xl flex items-center justify-center mb-6 border border-emerald-500/20 shadow-inner">
