          {/* SCAN BUTTON - Absolute positioned within the camera container */}
          {isCameraActive && !capturedImage && (
            <div className="absolute bottom-6 left-0 right-0 flex justify-center z-20">
              <button 
                onClick={handleAnalyze}
                disabled={isAnalyzing}
                className="group relative w-16 h-16 sm:w-20 sm:h-20 rounded-full border-4 border-white/20 flex items-center justify-center p-1.5 hover:border-emerald-500/40 transition-all bg-black/40 backdrop-blur-xl disabled:opacity-50 active:scale-90 shadow-2xl"
