import React, { useState, useRef, useEffect, useCallback } from 'react';
import { GoogleGenAI, Type, Modality } from '@google/genai';
import { Header } from './components/Header';
import { ClassificationCard } from './components/ClassificationCard';
import { TrashCategory, GroundingLink, ClassificationResult } from './types';
import { sounds } from './utils/sound-effects';
import { decode, decodeAudioData } from './utils/audio-utils';
import { AlertCircle, RotateCcw, Camera, Scan, Loader2, RefreshCcw, ShieldCheck, MapPin, Eye } from 'lucide-react';

const App: React.FC = () => {
  // UI States
  const [isCameraActive, setIsCameraActive] = useState(false);
  const [isInitializingCamera, setIsInitializingCamera] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [isSearchingCenters, setIsSearchingCenters] = useState(false);
  const [isReadingAloud, setIsReadingAloud] = useState(false);

  // Data States
  const [currentCategory, setCurrentCategory] = useState<TrashCategory>(TrashCategory.UNKNOWN);
  const [itemLabel, setItemLabel] = useState("");
  const [reason, setReason] = useState("");
  const [confidence, setConfidence] = useState(0);
  const [error, setError] = useState<string | null>(null);
  const [capturedImage, setCapturedImage] = useState<string | null>(null);
  const [groundingLinks, setGroundingLinks] = useState<GroundingLink[]>([]);
  const [userLocation, setUserLocation] = useState<{ latitude: number; longitude: number } | null>(null);

  // Refs for hardware/media
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const streamRef = useRef<MediaStream | null>(null);
  const audioCtxRef = useRef<AudioContext | null>(null);

  // Initialize geolocation once
  useEffect(() => {
    if (navigator.geolocation) {
      navigator.geolocation.getCurrentPosition(
        (pos) => setUserLocation({ latitude: pos.coords.latitude, longitude: pos.coords.longitude }),
        (err) => console.warn("Geolocation warning:", err.message)
      );
    }
    return () => {
      stopCamera();
    };
  }, []);

  // Ensure stream stays attached to video element if it's active
  useEffect(() => {
    if (isCameraActive && streamRef.current && videoRef.current && !videoRef.current.srcObject) {
      videoRef.current.srcObject = streamRef.current;
      videoRef.current.play().catch(e => console.error("Auto-play failed:", e));
    }
  }, [isCameraActive, capturedImage]);

  const stopCamera = () => {
    if (streamRef.current) {
      streamRef.current.getTracks().forEach(track => track.stop());
      streamRef.current = null;
    }
    if (videoRef.current) {
      videoRef.current.srcObject = null;
    }
    setIsCameraActive(false);
  };

  const startCamera = async () => {
    if (isInitializingCamera) return;

    setIsInitializingCamera(true);
    setError(null);
    stopCamera(); // Clean start

    try {
      const stream = await navigator.mediaDevices.getUserMedia({
        video: { 
          facingMode: 'environment',
          width: { ideal: 1280 },
          height: { ideal: 720 }
        },
        audio: false
      });

      streamRef.current = stream;
      if (videoRef.current) {
        videoRef.current.srcObject = stream;
        videoRef.current.onloadedmetadata = () => {
          videoRef.current?.play().catch(e => console.error("Playback error:", e));
        };
      }

      setIsCameraActive(true);
      resetScanner(false);
      sounds.playConnected();
    } catch (err: any) {
      console.error("Camera error:", err);
      let msg = "Camera access failed.";
      if (err.name === 'NotAllowedError') msg = "Permission denied. Please enable camera access.";
      else if (err.name === 'NotFoundError') msg = "No camera found on this device.";
      else msg = "Could not access camera. Check if another app is using it.";

      setError(msg);
      sounds.playError();
    } finally {
      setIsInitializingCamera(false);
    }
  };

  const captureFrame = () => {
    if (!videoRef.current || !canvasRef.current) return null;

    const canvas = canvasRef.current;
    const video = videoRef.current;

    if (video.readyState < 2) {
      setError("Camera feed not ready. Please wait a moment.");
      return null;
    }

    canvas.width = video.videoWidth;
    canvas.height = video.videoHeight;

    const ctx = canvas.getContext('2d');
    if (!ctx) return null;

    ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
    const dataUrl = canvas.toDataURL('image/jpeg', 0.85);
    setCapturedImage(dataUrl);
    return dataUrl;
  };

  const speakText = async (textToSpeak: string) => {
    if (!textToSpeak || isReadingAloud) return;
    setIsReadingAloud(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: "gemini-2.5-flash-preview-tts",
        contents: [{ parts: [{ text: textToSpeak }] }],
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } } },
        },
      });

      const audioData = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
      if (audioData) {
        if (!audioCtxRef.current) {
          audioCtxRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
        }
        const buffer = await decodeAudioData(decode(audioData), audioCtxRef.current);
        const source = audioCtxRef.current.createBufferSource();
        source.buffer = buffer;
        source.connect(audioCtxRef.current.destination);
        source.onended = () => setIsReadingAloud(false);
        source.start();
      } else {
        setIsReadingAloud(false);
      }
    } catch (err) {
      console.error("TTS error:", err);
      setIsReadingAloud(false);
    }
  };

  const handleAnalyze = async () => {
    if (isAnalyzing) return;

    const imageData = captureFrame();
    if (!imageData) return;

    setIsAnalyzing(true);
    setError(null);
    setItemLabel("");
    setReason("");
    setConfidence(0);
    setGroundingLinks([]);
    sounds.playHoldSteady();

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const base64Data = imageData.split(',')[1];

      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: [
          {
            parts: [
              { text: "Identify this waste item. Classify it into RECYCLE, ORGANIC, TRASH, HAZARDOUS, ELECTRONIC, or TEXTILE. Return a JSON object with 'item', 'category', 'confidence', 'reason', and 'disposalInstructions'. Confidence should be a number between 0 and 1." },
              { inlineData: { mimeType: 'image/jpeg', data: base64Data } }
            ]
          }
        ],
        config: {
          responseMimeType: 'application/json',
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              item: { type: Type.STRING },
              category: { type: Type.STRING, enum: Object.values(TrashCategory) },
              confidence: { type: Type.NUMBER },
              reason: { type: Type.STRING },
              disposalInstructions: { type: Type.STRING }
            },
            required: ['item', 'category', 'reason', 'confidence']
          }
        }
      });

      const textResponse = response.text;
      if (!textResponse) throw new Error("Empty response from AI");

      const result = JSON.parse(textResponse) as ClassificationResult;
      setItemLabel(result.item);
      const fullReason = `${result.reason} ${result.disposalInstructions || ''}`;
      setReason(fullReason);
      setCurrentCategory(result.category);
      setConfidence(result.confidence || 0);

      // Play category sound
      switch (result.category) {
        case TrashCategory.RECYCLE: sounds.playRecycle(); break;
        case TrashCategory.ORGANIC: sounds.playOrganic(); break;
        case TrashCategory.TRASH: sounds.playTrash(); break;
        default: sounds.playSpecial(); break;
      }
      sounds.playSuccess();

      // AUTO PLAY: Speak the findings
      speakText(`Identified as ${result.item}. ${fullReason}`);

    } catch (err: any) {
      console.error("Analysis error:", err);
      setError("Analysis failed. Please try again with a clearer view of the item.");
      sounds.playError();
      setCapturedImage(null);
    } finally {
      setIsAnalyzing(false);
    }
  };

  const handleFindCenters = async () => {
    if (!itemLabel || isSearchingCenters) return;
    setIsSearchingCenters(true);
    setError(null);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const prompt = `Find specialized recycling or disposal centers for ${itemLabel} near me.`;

      const response = await ai.models.generateContent({
        model: 'gemini-2.5-flash',
        contents: prompt,
        config: {
          tools: [{ googleMaps: {} }],
          toolConfig: {
            retrievalConfig: {
              latLng: userLocation || { latitude: 0, longitude: 0 }
            }
          }
        }
      });

      const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];
      const links = chunks
        .filter(c => c.maps)
        .map(c => ({ title: c.maps?.title || "Disposal Center", uri: c.maps?.uri || "" }));

      setGroundingLinks(links);
      if (links.length === 0) setError("No nearby facilities found for this specific item.");
      else sounds.playSuccess();
    } catch (err) {
      setError("Could not search for local centers.");
    } finally {
      setIsSearchingCenters(false);
    }
  };

  const resetScanner = (full: boolean = true) => {
    setCapturedImage(null);
    if (full) {
      setCurrentCategory(TrashCategory.UNKNOWN);
      setItemLabel("");
      setReason("");
      setConfidence(0);
      setGroundingLinks([]);
      setError(null);
    }
  };

  return (
    <div className="min-h-screen bg-slate-950 text-white font-sans flex flex-col overflow-auto">
      <Header isConnected={isCameraActive} />

      <main className="flex-1 container mx-auto px-4 pt-24 pb-12 max-w-6xl flex flex-col lg:flex-row items-stretch lg:items-start gap-6 lg:gap-10">

        {/* Optical Engine Container (Camera/Image View) */}
        <div className="relative w-full lg:flex-1 aspect-[4/3] sm:aspect-video lg:aspect-auto lg:h-[calc(100vh-10rem)] max-h-[60vh] lg:max-h-none rounded-[2.5rem] overflow-hidden bg-slate-900 border border-slate-800 shadow-2xl ring-1 ring-white/10 transition-all duration-700">

          <video 
            ref={videoRef} 
            autoPlay 
            playsInline 
            muted
            className={`w-full h-full object-cover transition-opacity duration-500 ${isCameraActive && !capturedImage ? 'opacity-100' : 'opacity-0 absolute inset-0'}`}
          />

          {isCameraActive && !capturedImage && (
            <div className="absolute inset-0 pointer-events-none flex flex-col items-center">
              <div className="mt-12 px-5 py-2 bg-emerald-500/20 backdrop-blur-xl rounded-full text-[10px] font-black tracking-[0.3em] text-emerald-400 border border-emerald-500/30 uppercase animate-pulse shadow-lg">
                Scanning for Target...
              </div>
              <div className="flex-1 flex items-center justify-center w-full">
                <div className="w-1/2 aspect-square max-w-[200px] border-2 border-emerald-500/20 rounded-3xl animate-pulse relative">
                  <div className="absolute top-0 left-0 w-4 h-4 border-t-2 border-l-2 border-emerald-400 rounded-tl-lg" />
                  <div className="absolute top-0 right-0 w-4 h-4 border-t-2 border-r-2 border-emerald-400 rounded-tr-lg" />
                  <div className="absolute bottom-0 left-0 w-4 h-4 border-b-2 border-l-2 border-emerald-400 rounded-bl-lg" />
                  <div className="absolute bottom-0 right-0 w-4 h-4 border-b-2 border-r-2 border-emerald-400 rounded-br-lg" />
                </div>
              </div>
            </div>
          )}

          {capturedImage && (
            <img src={capturedImage} className="absolute inset-0 w-full h-full object-cover" alt="Captured waste" />
          )}

          {/* REQUEST ACCESS SCENE (INITIAL STANDBY STATE) */}
          {!isCameraActive && !isInitializingCamera && (
            <div className="absolute inset-0 flex flex-col items-center justify-center p-6 text-center bg-slate-900/95 backdrop-blur-xl">
              <div className="mb-8 relative">
                <div className="w-24 h-24 bg-emerald-500/10 rounded-full flex items-center justify-center border border-emerald-500/20 shadow-[0_0_50px_rgba(16,185,129,0.1)]">
                  <ShieldCheck className="w-12 h-12 text-emerald-500" />
                </div>
                <div className="absolute -top-2 -right-2 w-8 h-8 bg-slate-800 rounded-full flex items-center justify-center border border-white/10 shadow-lg">
                  <div className="w-2 h-2 bg-rose-500 rounded-full animate-pulse" />
                </div>
              </div>

              <h2 className="text-2xl sm:text-3xl font-black mb-4 tracking-tight text-white uppercase">System Standby</h2>
              <p className="text-slate-400 text-sm font-medium mb-8 leading-relaxed max-w-sm mx-auto">
                To begin waste classification, EcoScan needs to activate your primary sensors.
              </p>

              <div className="grid grid-cols-2 gap-4 w-full max-w-xs mb-10">
                <div className="p-4 bg-white/5 rounded-2xl border border-white/10 flex flex-col items-center gap-2">
                  <Eye className="w-5 h-5 text-emerald-400" />
                  <span className="text-[10px] font-black tracking-widest uppercase opacity-60">Optical</span>
                </div>
                <div className="p-4 bg-white/5 rounded-2xl border border-white/10 flex flex-col items-center gap-2">
                  <MapPin className="w-5 h-5 text-blue-400" />
                  <span className="text-[10px] font-black tracking-widest uppercase opacity-60">Geo-Nav</span>
                </div>
              </div>

              <button 
                onClick={startCamera}
                className="group relative flex items-center gap-4 px-10 py-5 bg-emerald-500 hover:bg-emerald-400 text-slate-950 rounded-2xl font-black text-xs uppercase tracking-[0.2em] transition-all active:scale-95 shadow-2xl shadow-emerald-500/30 ring-4 ring-emerald-500/20"
              >
                <Scan className="w-5 h-5" />
                Enable System Senses
              </button>

              <p className="mt-8 text-[9px] font-black tracking-[0.4em] uppercase text-white/20">Secured by Gemini AI</p>
            </div>
          )}

          {isInitializingCamera && (
            <div className="absolute inset-0 flex flex-col items-center justify-center gap-4 bg-slate-900">
              <Loader2 className="w-8 h-8 text-emerald-500 animate-spin" />
              <p className="text-[9px] font-black tracking-[0.4em] uppercase text-emerald-500/50">Synchronizing Sensors...</p>
            </div>
          )}

          {/* SCAN BUTTON */}
          {isCameraActive && !capturedImage && (
            <div className="absolute bottom-6 left-0 right-0 flex justify-center z-20">
              <button 
                onClick={handleAnalyze}
                disabled={isAnalyzing}
                className="group relative w-16 h-16 sm:w-20 sm:h-20 rounded-full border-4 border-white/20 flex items-center justify-center p-1.5 hover:border-emerald-500/40 transition-all bg-black/40 backdrop-blur-xl disabled:opacity-50 active:scale-90 shadow-2xl"
              >
                <div className="w-full h-full rounded-full bg-white shadow-inner flex items-center justify-center overflow-hidden">
                  {isAnalyzing && <Loader2 className="w-6 h-6 sm:w-8 sm:h-8 text-emerald-600 animate-spin" />}
                  {!isAnalyzing && <div className="w-full h-full bg-white group-hover:bg-emerald-50 transition-colors" />}
                </div>
              </button>
            </div>
          )}

          {error && (
            <div className="absolute top-4 left-4 right-4 bg-rose-600/90 backdrop-blur-xl text-white p-4 rounded-2xl flex items-center gap-3 shadow-2xl border border-rose-400/20 animate-in fade-in slide-in-from-top-4 z-50">
              <AlertCircle className="w-5 h-5 shrink-0" />
              <div className="flex-1">
                <p className="text-[10px] sm:text-xs font-bold leading-tight tracking-wide">{error}</p>
              </div>
              <button 
                onClick={() => isCameraActive ? resetScanner(true) : startCamera()} 
                className="bg-white/20 p-2 rounded-xl hover:bg-white/30 transition-colors"
              >
                <RefreshCcw className="w-4 h-4" />
              </button>
            </div>
          )}
        </div>

        {/* Results Panel */}
        <div className="w-full lg:w-[420px] shrink-0 flex flex-col gap-6">
          <ClassificationCard 
            category={currentCategory}
            item={itemLabel}
            confidence={confidence}
            reason={reason}
            locationAccess={!!userLocation}
            links={groundingLinks}
            isAnalyzing={isAnalyzing}
            isSearchingCenters={isSearchingCenters}
            onFindCenters={handleFindCenters}
            isReadingAloud={isReadingAloud}
            onReadAloud={() => speakText(`Identified as ${itemLabel}. Recommendation: ${reason}`)}
          />

          {capturedImage && !isAnalyzing && (
            <button 
              onClick={() => resetScanner(true)}
              className="w-full py-4 flex items-center justify-center gap-3 text-slate-500 hover:text-white transition-all font-black text-[11px] uppercase tracking-[0.4em] bg-white/5 hover:bg-white/10 rounded-2xl border border-white/5"
            >
              <RotateCcw className="w-4 h-4" />
              Clear Current Feed
            </button>
          )}
        </div>
      </main>

      <canvas ref={canvasRef} className="hidden" />
    </div>
  );
};

